insert into daily_topics (slug, title, vn_title, icon, color, description, phrases, vocab, tips, dialogue, sort_order, published) values
('greetings', 'Greetings & Small Talk', 'Chào hỏi & Chuyện phiếm', '👋', '#3b82f6', '12 phrases · 4 vocab items', '[{"id":"daily-greetings-001","en":"Good morning! How are you doing today?","vn":"Chào buổi sáng! Hôm nay bạn thế nào?","note":"Câu mở đầu lịch sự nhất"},{"id":"daily-greetings-002","en":"I''m doing great, thanks for asking!","vn":"Tôi rất tốt, cảm ơn bạn đã hỏi!","note":""},{"id":"daily-greetings-003","en":"Not bad, could be better. How about you?","vn":"Cũng ổn thôi, có thể tốt hơn. Còn bạn thì sao?","note":"Câu trung thực nhưng lịch sự"},{"id":"daily-greetings-004","en":"Long time no see! What have you been up to?","vn":"Lâu không gặp! Dạo này bạn làm gì vậy?","note":""},{"id":"daily-greetings-005","en":"It''s been a while. You look great!","vn":"Lâu rồi không gặp. Bạn trông rất tốt!","note":""},{"id":"daily-greetings-006","en":"What a small world — fancy meeting you here!","vn":"Thế giới thật nhỏ — thật trùng hợp khi gặp bạn ở đây!","note":"Khi gặp người quen bất ngờ"},{"id":"daily-greetings-007","en":"I''m sorry, I didn''t catch your name?","vn":"Xin lỗi, tôi chưa kịp nghe tên bạn?","note":"Lịch sự khi không nghe rõ tên"},{"id":"daily-greetings-008","en":"It''s nice to meet you. I''m [name].","vn":"Rất vui được gặp bạn. Tôi là [tên].","note":""},{"id":"daily-greetings-009","en":"How''s the family?","vn":"Gia đình bạn thế nào rồi?","note":""},{"id":"daily-greetings-010","en":"I''ve been keeping busy. Work has been hectic lately.","vn":"Tôi khá bận. Công việc dạo này hơi hối hả.","note":"hectic = bận rộn, hối hả"},{"id":"daily-greetings-011","en":"Anyway, it was great running into you!","vn":"Dù sao, thật vui khi tình cờ gặp bạn!","note":"Câu khi chia tay"},{"id":"daily-greetings-012","en":"Take care! See you around.","vn":"Bảo trọng nhé! Hẹn gặp lại.","note":""}]', '[{"id":"daily-greetings-vocab-1","word":"hectic","phonetic":"/ˈhektɪk/","meaning":"bận rộn, hối hả"},{"id":"daily-greetings-vocab-2","word":"run into","phonetic":"/rʌn ˈɪntʊ/","meaning":"tình cờ gặp ai đó"},{"id":"daily-greetings-vocab-3","word":"catch up","phonetic":"/kætʃ ʌp/","meaning":"gặp gỡ, cập nhật tin tức nhau"},{"id":"daily-greetings-vocab-4","word":"fancy","phonetic":"/ˈfænsi/","meaning":"(Anh) ngạc nhiên, ai ngờ"}]', '["Người Anh/Mỹ thường hỏi ''How are you?'' mà không cần câu trả lời chi tiết — ''Fine, thanks!'' là đủ.","Khi không nghe rõ tên: ''Sorry, could you spell that for me?'' — Xin lỗi, bạn có thể đánh vần không?","Small talk phổ biến: thời tiết, cuối tuần, công việc, thể thao — tránh nói chính trị hoặc thu nhập."]', '[{"id":"daily-greetings-dial-1","speaker":"A","en":"Hey James! Long time no see. How have you been?","vn":"Ê James! Lâu quá không gặp. Bạn có khỏe không?"},{"id":"daily-greetings-dial-2","speaker":"B","en":"Oh wow, it''s great to see you! I''ve been really well, just busy with work.","vn":"Ôi, thật tuyệt khi gặp bạn! Tôi vẫn khỏe, chỉ là bận công việc thôi."},{"id":"daily-greetings-dial-3","speaker":"A","en":"I know the feeling! Are you still at City Hospital?","vn":"Tôi hiểu cảm giác đó! Bạn vẫn làm ở Bệnh viện Thành phố không?"},{"id":"daily-greetings-dial-4","speaker":"B","en":"Yes, still there. What about you?","vn":"Vâng, vẫn ở đó. Còn bạn thì sao?"},{"id":"daily-greetings-dial-5","speaker":"A","en":"Same. Listen, we should catch up properly. Coffee sometime?","vn":"Như cũ. Này, chúng ta nên gặp nhau kỹ hơn. Uống cà phê hôm nào đó không?"},{"id":"daily-greetings-dial-6","speaker":"B","en":"Absolutely! I''ll text you.","vn":"Nhất định rồi! Tôi sẽ nhắn tin cho bạn."}]', 0, true),
('cafe', 'Café & Coffee Shop', 'Quán cà phê', '☕', '#a16207', '12 phrases · 5 vocab items', '[{"id":"daily-cafe-001","en":"Hi, can I get a medium latte, please?","vn":"Xin chào, cho tôi một ly latte cỡ vừa nhé?","note":"medium = cỡ vừa (Starbucks: tall/grande/venti)"},{"id":"daily-cafe-002","en":"Could I have that with oat milk instead?","vn":"Bạn có thể dùng sữa yến mạch thay thế không?","note":"oat milk = sữa yến mạch; popular substitution"},{"id":"daily-cafe-003","en":"Make it decaf, please.","vn":"Không cà phê nhé (decaf).","note":"decaf = không caffeine"},{"id":"daily-cafe-004","en":"Can I have an extra shot of espresso?","vn":"Cho thêm một shot espresso được không?","note":"extra shot = thêm một phần espresso"},{"id":"daily-cafe-005","en":"Is this seat taken?","vn":"Ghế này có ai ngồi chưa?","note":"Câu hỏi khi muốn ngồi cạnh người lạ"},{"id":"daily-cafe-006","en":"Do you have free Wi-Fi here? What''s the password?","vn":"Ở đây có Wi-Fi miễn phí không? Mật khẩu là gì?","note":""},{"id":"daily-cafe-007","en":"Could I get this to go?","vn":"Tôi có thể lấy mang về không?","note":"to go = mang về; dine in = ăn tại chỗ"},{"id":"daily-cafe-008","en":"I''ll have the same as her.","vn":"Cho tôi giống như của cô ấy.","note":"Câu nhanh gọn khi muốn gọi giống người khác"},{"id":"daily-cafe-009","en":"Can I get a refill?","vn":"Tôi có thể xin thêm không?","note":"refill = rót thêm (thường miễn phí ở Mỹ)"},{"id":"daily-cafe-010","en":"Do you have any dairy-free options?","vn":"Bạn có lựa chọn không có sữa không?","note":"dairy-free = không chứa sản phẩm từ sữa"},{"id":"daily-cafe-011","en":"I''d like to order a slice of cheesecake too.","vn":"Cho tôi thêm một miếng cheesecake nữa.","note":""},{"id":"daily-cafe-012","en":"Could I get a receipt?","vn":"Cho tôi hóa đơn được không?","note":""}]', '[{"id":"daily-cafe-vocab-1","word":"decaf","phonetic":"/ˈdiːkæf/","meaning":"cà phê không caffeine"},{"id":"daily-cafe-vocab-2","word":"to go","phonetic":"/tə ɡəʊ/","meaning":"mang về"},{"id":"daily-cafe-vocab-3","word":"refill","phonetic":"/ˈriːfɪl/","meaning":"rót thêm, nạp lại"},{"id":"daily-cafe-vocab-4","word":"alternative","phonetic":"/ɔːlˈtɜːnətɪv/","meaning":"sự lựa chọn thay thế"},{"id":"daily-cafe-vocab-5","word":"Keep the change","phonetic":"","meaning":"Giữ tiền thối lại (boa)"}]', '["Ở Mỹ, tip khoảng 15-20% là thông lệ, kể cả ở quán cà phê.","''Can I get...'' tự nhiên hơn ''I want...'' khi gọi đồ ở quán.","Phân biệt: ''for here'' (ăn tại chỗ) vs ''to go'' (mang về)."]', '[{"id":"daily-cafe-dial-1","speaker":"Barista","en":"Hi there! What can I get for you today?","vn":"Xin chào! Hôm nay bạn muốn gọi gì?"},{"id":"daily-cafe-dial-2","speaker":"You","en":"Hi! I''d like a grande cappuccino, please.","vn":"Xin chào! Cho tôi một cappuccino cỡ vừa lớn."},{"id":"daily-cafe-dial-3","speaker":"Barista","en":"Sure! Whole milk or would you like an alternative?","vn":"Được! Sữa nguyên kem hay bạn muốn loại khác?"},{"id":"daily-cafe-dial-4","speaker":"You","en":"Oat milk please. And could I add an extra shot?","vn":"Sữa yến mạch nhé. Và cho thêm một shot espresso được không?"},{"id":"daily-cafe-dial-5","speaker":"Barista","en":"Of course! For here or to go?","vn":"Dĩ nhiên! Uống tại đây hay mang về?"},{"id":"daily-cafe-dial-6","speaker":"You","en":"To go, please. And your Wi-Fi password?","vn":"Mang về nhé. Và mật khẩu Wi-Fi của bạn là gì?"},{"id":"daily-cafe-dial-7","speaker":"Barista","en":"It''s on the board — CafeBlue2025. That''ll be $6.50.","vn":"Trên bảng đó — CafeBlue2025. Tổng cộng là 6.50$."},{"id":"daily-cafe-dial-8","speaker":"You","en":"Here you go. Keep the change!","vn":"Đây nhé. Bạn giữ tiền thối lại đi!"}]', 1, true),
('restaurant', 'Restaurant — Dining Out', 'Nhà hàng — Ăn ngoài', '🍽️', '#dc2626', '13 phrases · 5 vocab items', '[{"id":"daily-restaurant-001","en":"Do you have a table for two available?","vn":"Bạn có bàn trống cho 2 người không?","note":""},{"id":"daily-restaurant-002","en":"I have a reservation under Dr. [Name] at 7 pm.","vn":"Tôi có đặt bàn với tên bác sĩ [Tên] lúc 7 giờ tối.","note":""},{"id":"daily-restaurant-003","en":"Could we see the menu, please?","vn":"Cho chúng tôi xem thực đơn được không?","note":""},{"id":"daily-restaurant-004","en":"What do you recommend? What''s the specialty here?","vn":"Bạn gợi ý món gì? Đặc sản ở đây là gì?","note":""},{"id":"daily-restaurant-005","en":"I''m allergic to shellfish — no shrimp, crab, or oyster.","vn":"Tôi dị ứng hải sản có vỏ — không tôm, cua, hay hàu.","note":"shellfish = hải sản có vỏ"},{"id":"daily-restaurant-006","en":"I''d like my steak medium-rare, please.","vn":"Cho tôi bít tết chín tái vừa nhé.","note":"rare/medium-rare/medium/well-done"},{"id":"daily-restaurant-007","en":"Could I substitute the fries for a salad?","vn":"Tôi có thể đổi khoai chiên lấy salad không?","note":"substitute = đổi, thay thế"},{"id":"daily-restaurant-008","en":"Excuse me, we''ve been waiting for 20 minutes.","vn":"Xin lỗi, chúng tôi đã đợi 20 phút rồi.","note":"Lịch sự nhưng rõ ràng"},{"id":"daily-restaurant-009","en":"This isn''t what I ordered. I asked for the salmon.","vn":"Đây không phải món tôi gọi. Tôi đã gọi cá hồi.","note":""},{"id":"daily-restaurant-010","en":"Could we get some more water, please?","vn":"Cho chúng tôi thêm nước được không?","note":""},{"id":"daily-restaurant-011","en":"Everything was delicious. Compliments to the chef.","vn":"Mọi thứ đều ngon. Khen đầu bếp giúp tôi nhé.","note":""},{"id":"daily-restaurant-012","en":"Could we get the bill please? We''ll split it.","vn":"Cho chúng tôi tính tiền nhé? Chúng tôi chia đôi.","note":"split the bill = chia tiền"},{"id":"daily-restaurant-013","en":"Is service charge included in the bill?","vn":"Phí phục vụ có bao gồm trong hóa đơn không?","note":""}]', '[{"id":"daily-restaurant-vocab-1","word":"medium-rare","phonetic":"/ˌmiːdiəm ˈreər/","meaning":"chín tái vừa (bít tết)"},{"id":"daily-restaurant-vocab-2","word":"substitute","phonetic":"/ˈsʌbstɪtjuːt/","meaning":"thay thế, đổi"},{"id":"daily-restaurant-vocab-3","word":"split","phonetic":"/splɪt/","meaning":"chia đôi (tiền)"},{"id":"daily-restaurant-vocab-4","word":"allergy","phonetic":"/ˈælərdʒi/","meaning":"dị ứng"},{"id":"daily-restaurant-vocab-5","word":"specialty","phonetic":"/ˈspeʃəlti/","meaning":"đặc sản, món đặc biệt"}]', '["Luôn đề cập dị ứng thực phẩm ngay khi ngồi vào bàn, trước khi gọi món.","Mức độ chín bít tết: rare (tái) → medium-rare → medium → medium-well → well-done (chín kỹ).","Ở Mỹ: tip 18-20%. Ở Anh/Úc: 10-15% hoặc tùy ý."]', '[{"id":"daily-restaurant-dial-1","speaker":"Waiter","en":"Good evening! Do you have a reservation?","vn":"Chào buổi tối! Quý khách có đặt bàn trước không?"},{"id":"daily-restaurant-dial-2","speaker":"You","en":"Yes, under Dr. Nguyen. A table for three.","vn":"Có, tên bác sĩ Nguyễn. Bàn cho 3 người."},{"id":"daily-restaurant-dial-3","speaker":"Waiter","en":"Right this way please. Here are your menus.","vn":"Mời quý khách theo tôi. Đây là thực đơn."},{"id":"daily-restaurant-dial-4","speaker":"You","en":"Thank you. What do you recommend tonight?","vn":"Cảm ơn. Tối nay bạn gợi ý món gì?"},{"id":"daily-restaurant-dial-5","speaker":"Waiter","en":"The grilled salmon and the ribeye steak are excellent tonight.","vn":"Cá hồi nướng và bít tết sườn cực kỳ ngon tối nay."},{"id":"daily-restaurant-dial-6","speaker":"You","en":"I''ll have the salmon. And could I have it with vegetables instead of fries?","vn":"Cho tôi cá hồi. Và cho tôi rau thay khoai chiên được không?"},{"id":"daily-restaurant-dial-7","speaker":"Waiter","en":"Of course! Any allergies I should know about?","vn":"Dĩ nhiên! Quý khách có dị ứng thực phẩm gì không?"},{"id":"daily-restaurant-dial-8","speaker":"You","en":"I''m allergic to shellfish. Please make sure the salmon hasn''t been near shrimp.","vn":"Tôi dị ứng hải sản có vỏ. Vui lòng đảm bảo cá hồi không tiếp xúc tôm."}]', 2, true),
('transport', 'Transportation & Getting Around', 'Di chuyển & Hỏi đường', '🚕', '#0891b2', '12 phrases · 5 vocab items', '[{"id":"daily-transport-001","en":"Could you take me to the Marriott Hotel on Nguyen Hue Street?","vn":"Bạn có thể đưa tôi đến khách sạn Marriott trên đường Nguyễn Huệ không?","note":""},{"id":"daily-transport-002","en":"How long will it take to get there?","vn":"Mất bao lâu để đến đó?","note":""},{"id":"daily-transport-003","en":"Could you please turn on the air conditioning?","vn":"Bạn có thể bật điều hòa được không?","note":""},{"id":"daily-transport-004","en":"Please drop me off at the corner.","vn":"Vui lòng để tôi xuống ở góc đường.","note":"drop off = để xuống (xe)"},{"id":"daily-transport-005","en":"Keep the change.","vn":"Bạn giữ tiền lẻ đi.","note":"Câu boa cho tài xế"},{"id":"daily-transport-006","en":"Excuse me, how do I get to the nearest subway station?","vn":"Xin lỗi, tôi đi đến trạm tàu điện ngầm gần nhất như thế nào?","note":""},{"id":"daily-transport-007","en":"Is this the right bus for the city centre?","vn":"Đây có phải xe buýt đi trung tâm thành phố không?","note":""},{"id":"daily-transport-008","en":"Where should I get off for the museum?","vn":"Tôi nên xuống trạm nào để đến bảo tàng?","note":"get off = xuống (xe buýt/tàu)"},{"id":"daily-transport-009","en":"I think I''m lost. Can you show me on the map?","vn":"Tôi nghĩ mình bị lạc. Bạn có thể chỉ cho tôi trên bản đồ không?","note":""},{"id":"daily-transport-010","en":"How far is it on foot from here?","vn":"Từ đây đi bộ bao xa?","note":"on foot = đi bộ"},{"id":"daily-transport-011","en":"Could you call me an Uber/Grab?","vn":"Bạn có thể gọi Uber/Grab cho tôi không?","note":""},{"id":"daily-transport-012","en":"I''ll be at the departures terminal in 10 minutes.","vn":"Tôi sẽ đến sảnh khởi hành trong 10 phút.","note":""}]', '[{"id":"daily-transport-vocab-1","word":"drop off","phonetic":"/drɒp ɒf/","meaning":"để xuống, dừng cho ai xuống xe"},{"id":"daily-transport-vocab-2","word":"on foot","phonetic":"/ɒn fʊt/","meaning":"đi bộ"},{"id":"daily-transport-vocab-3","word":"get off","phonetic":"/ɡet ɒf/","meaning":"xuống xe buýt/tàu"},{"id":"daily-transport-vocab-4","word":"toll","phonetic":"/toʊl/","meaning":"phí cầu đường"},{"id":"daily-transport-vocab-5","word":"expressway","phonetic":"/ˈeksprɛsweɪ/","meaning":"đường cao tốc"}]', '["Luôn nói địa chỉ rõ ràng: số nhà + tên đường + khu vực. Ví dụ: ''42 Baker Street, Marylebone''.","''Excuse me'' trước khi hỏi đường — bao giờ cũng lịch sự hơn.","Khi không hiểu chỉ đường: ''Could you write that down for me?'' — Bạn có thể viết ra cho tôi không?"]', '[{"id":"daily-transport-dial-1","speaker":"You","en":"Hi, I need to get to St. Mary''s Hospital. How long will that take?","vn":"Xin chào, tôi cần đến Bệnh viện St. Mary''s. Mất bao lâu?"},{"id":"daily-transport-dial-2","speaker":"Driver","en":"About 20 minutes in this traffic. Is that okay?","vn":"Khoảng 20 phút trong tình trạng kẹt xe này. Được không?"},{"id":"daily-transport-dial-3","speaker":"You","en":"That''s fine. Could you take the expressway? I''m running a bit late.","vn":"Được rồi. Bạn có thể đi đường cao tốc không? Tôi hơi trễ giờ rồi."},{"id":"daily-transport-dial-4","speaker":"Driver","en":"Sure. There''s a toll — about $2. Is that all right?","vn":"Được. Có phí cầu đường — khoảng 2$. Được không?"},{"id":"daily-transport-dial-5","speaker":"You","en":"No problem. Actually, please stop at the main entrance.","vn":"Không vấn đề. Thực ra, cho tôi xuống ở cổng chính nhé."},{"id":"daily-transport-dial-6","speaker":"Driver","en":"Here we are. That''s $18.50.","vn":"Đến rồi. 18.50$."},{"id":"daily-transport-dial-7","speaker":"You","en":"Here''s $20. Keep the change.","vn":"Đây 20$. Bạn giữ tiền lẻ đi."}]', 3, true),
('shopping', 'Shopping & Pharmacy', 'Mua sắm & Nhà thuốc', '🛍️', '#7c3aed', '12 phrases · 5 vocab items', '[{"id":"daily-shopping-001","en":"I''m just browsing, thank you.","vn":"Tôi chỉ đang xem thôi, cảm ơn.","note":"Khi nhân viên hỏi có cần giúp không"},{"id":"daily-shopping-002","en":"Do you have this in a larger size?","vn":"Bạn có cái này size lớn hơn không?","note":""},{"id":"daily-shopping-003","en":"Could I try this on? Where''s the fitting room?","vn":"Tôi có thể mặc thử không? Phòng thử đồ ở đâu?","note":""},{"id":"daily-shopping-004","en":"This is a bit tight. Do you have the next size up?","vn":"Cái này hơi chật. Bạn có size lớn hơn một bậc không?","note":""},{"id":"daily-shopping-005","en":"Is this on sale? Do you have any discounts?","vn":"Cái này có đang giảm giá không?","note":""},{"id":"daily-shopping-006","en":"Do you do tax refunds for tourists?","vn":"Bạn có hoàn thuế cho khách du lịch không?","note":"tax refund = hoàn thuế"},{"id":"daily-shopping-007","en":"Could I return this if it doesn''t fit?","vn":"Tôi có thể trả lại nếu không vừa không?","note":""},{"id":"daily-shopping-008","en":"Do you have ibuprofen over the counter?","vn":"Bạn có ibuprofen bán không cần toa không?","note":"over the counter = không cần toa thuốc"},{"id":"daily-shopping-009","en":"I need something for a cold and a sore throat.","vn":"Tôi cần thuốc cho cảm lạnh và đau họng.","note":""},{"id":"daily-shopping-010","en":"Is this medication safe to take with antibiotics?","vn":"Thuốc này có an toàn khi dùng cùng kháng sinh không?","note":""},{"id":"daily-shopping-011","en":"What are the dosage instructions?","vn":"Hướng dẫn liều dùng là gì?","note":"dosage = liều dùng"},{"id":"daily-shopping-012","en":"Do I need a prescription for this?","vn":"Tôi có cần toa thuốc cho loại này không?","note":"prescription = toa thuốc"}]', '[{"id":"daily-shopping-vocab-1","word":"over the counter","phonetic":"/ˌoʊvər ðə ˈkaʊntər/","meaning":"thuốc không cần toa"},{"id":"daily-shopping-vocab-2","word":"prescription","phonetic":"/prɪˈskrɪpʃən/","meaning":"toa thuốc"},{"id":"daily-shopping-vocab-3","word":"dosage","phonetic":"/ˈdoʊsɪdʒ/","meaning":"liều dùng"},{"id":"daily-shopping-vocab-4","word":"lozenge","phonetic":"/ˈlɒzɪndʒ/","meaning":"kẹo ngậm ho"},{"id":"daily-shopping-vocab-5","word":"fitting room","phonetic":"/ˈfɪtɪŋ ruːm/","meaning":"phòng thử đồ"}]', '["Ở nhà thuốc nước ngoài: luôn mang toa thuốc gốc khi cần mua thuốc kê đơn.","''I''m browsing'' = đang xem thôi, không cần người bán hàng theo sát.","Hỏi về tương tác thuốc: ''Does this interact with...?'' — Thuốc này có tương tác với... không?"]', '[{"id":"daily-shopping-dial-1","speaker":"Pharmacist","en":"Hi, can I help you with anything?","vn":"Xin chào, tôi có thể giúp gì cho bạn?"},{"id":"daily-shopping-dial-2","speaker":"You","en":"Yes please. I have a bad cold and a really sore throat.","vn":"Vâng, cảm ơn. Tôi bị cảm nặng và đau họng dữ lắm."},{"id":"daily-shopping-dial-3","speaker":"Pharmacist","en":"How long have you had the symptoms?","vn":"Bạn bị triệu chứng này bao lâu rồi?"},{"id":"daily-shopping-dial-4","speaker":"You","en":"Since yesterday. I also have a slight fever — 37.8.","vn":"Từ hôm qua. Tôi cũng sốt nhẹ — 37.8 độ."},{"id":"daily-shopping-dial-5","speaker":"Pharmacist","en":"Are you currently taking any other medication?","vn":"Bạn đang dùng thuốc nào khác không?"},{"id":"daily-shopping-dial-6","speaker":"You","en":"Yes, I''m on a course of amoxicillin.","vn":"Vâng, tôi đang uống amoxicillin."},{"id":"daily-shopping-dial-7","speaker":"Pharmacist","en":"In that case I''d recommend this paracetamol and these throat lozenges. They''re safe with antibiotics.","vn":"Trong trường hợp đó tôi khuyên dùng paracetamol này và kẹo ngậm ho này. Chúng an toàn với kháng sinh."},{"id":"daily-shopping-dial-8","speaker":"You","en":"Thank you. What''s the dosage for the paracetamol?","vn":"Cảm ơn. Liều dùng paracetamol là bao nhiêu?"}]', 4, true),
('hotel', 'Hotel — Check-in & Stay', 'Khách sạn', '🏨', '#059669', '12 phrases · 5 vocab items', '[{"id":"daily-hotel-001","en":"I have a reservation. The name is Dr. Nguyen.","vn":"Tôi có đặt phòng. Tên là bác sĩ Nguyễn.","note":""},{"id":"daily-hotel-002","en":"Could I have a room with a higher floor?","vn":"Tôi có thể có phòng tầng cao hơn không?","note":""},{"id":"daily-hotel-003","en":"Is the breakfast included?","vn":"Bữa sáng có bao gồm không?","note":""},{"id":"daily-hotel-004","en":"What time is checkout?","vn":"Checkout lúc mấy giờ?","note":""},{"id":"daily-hotel-005","en":"Could I request a late checkout — around noon?","vn":"Tôi có thể xin checkout muộn — khoảng trưa không?","note":"late checkout = checkout muộn hơn giờ quy định"},{"id":"daily-hotel-006","en":"The air conditioning doesn''t seem to be working.","vn":"Điều hòa không chạy được.","note":""},{"id":"daily-hotel-007","en":"There''s no hot water in my room.","vn":"Phòng tôi không có nước nóng.","note":""},{"id":"daily-hotel-008","en":"Could I get some extra towels and toiletries?","vn":"Cho tôi xin thêm khăn và đồ vệ sinh cá nhân.","note":"toiletries = đồ vệ sinh cá nhân"},{"id":"daily-hotel-009","en":"Could you arrange an airport transfer for 6 am?","vn":"Bạn có thể sắp xếp xe đưa ra sân bay lúc 6 giờ sáng không?","note":""},{"id":"daily-hotel-010","en":"I''d like to extend my stay by one night.","vn":"Tôi muốn ở thêm một đêm nữa.","note":""},{"id":"daily-hotel-011","en":"Can I leave my luggage here while I check out?","vn":"Tôi có thể để hành lý ở đây trong khi checkout không?","note":""},{"id":"daily-hotel-012","en":"Could you recommend a good local restaurant nearby?","vn":"Bạn có thể giới thiệu một nhà hàng địa phương ngon gần đây không?","note":""}]', '[{"id":"daily-hotel-vocab-1","word":"late checkout","phonetic":"/leɪt ˈtʃekaʊt/","meaning":"trả phòng muộn hơn giờ quy định"},{"id":"daily-hotel-vocab-2","word":"toiletries","phonetic":"/ˈtɔɪlətriz/","meaning":"đồ vệ sinh cá nhân (dầu gội, xà phòng...)"},{"id":"daily-hotel-vocab-3","word":"luggage","phonetic":"/ˈlʌɡɪdʒ/","meaning":"hành lý"},{"id":"daily-hotel-vocab-4","word":"transfer","phonetic":"/ˈtrænsfer/","meaning":"xe đưa đón"},{"id":"daily-hotel-vocab-5","word":"amenities","phonetic":"/əˈmiːnɪtiz/","meaning":"tiện nghi, dịch vụ"}]', '["Khi check-in, luôn hỏi về late checkout — thường miễn phí nếu phòng không có khách.","Nếu phòng có vấn đề: báo ngay để được đổi phòng hoặc giảm giá.","Giữ key card đến khi checkout — thường cũng là thẻ tiêu mini-bar."]', '[{"id":"daily-hotel-dial-1","speaker":"Receptionist","en":"Welcome to the Grand Hotel. How can I help?","vn":"Chào mừng đến Grand Hotel. Tôi có thể giúp gì?"},{"id":"daily-hotel-dial-2","speaker":"You","en":"Hello. I have a reservation under Dr. Nguyen, checking in for 3 nights.","vn":"Xin chào. Tôi có đặt phòng tên bác sĩ Nguyễn, nhận phòng 3 đêm."},{"id":"daily-hotel-dial-3","speaker":"Receptionist","en":"Let me pull up your reservation. Could I see your passport?","vn":"Để tôi tra đặt phòng. Cho tôi xem hộ chiếu được không?"},{"id":"daily-hotel-dial-4","speaker":"You","en":"Of course. Here you go. Is it possible to get a room on a higher floor?","vn":"Dĩ nhiên. Đây nhé. Có thể có phòng ở tầng cao hơn không?"},{"id":"daily-hotel-dial-5","speaker":"Receptionist","en":"Certainly. I''ve given you room 1402. Checkout is at noon. Is there anything else?","vn":"Dĩ nhiên. Tôi đã xếp phòng 1402. Checkout lúc 12 giờ trưa. Có gì khác không?"},{"id":"daily-hotel-dial-6","speaker":"You","en":"Is breakfast included? And do you have the Wi-Fi password?","vn":"Bữa sáng có bao gồm không? Và mật khẩu Wi-Fi là gì?"},{"id":"daily-hotel-dial-7","speaker":"Receptionist","en":"Breakfast is from 7 to 10 in the restaurant on level 2. Wi-Fi is on your key card.","vn":"Bữa sáng từ 7 đến 10 giờ ở nhà hàng tầng 2. Wi-Fi ở trên thẻ chìa khóa."}]', 5, true),
('phone', 'Phone Calls & Appointments', 'Điện thoại & Đặt lịch hẹn', '📞', '#0284c7', '12 phrases · 5 vocab items', '[{"id":"daily-phone-001","en":"Hello, this is Dr. Nguyen calling.","vn":"Xin chào, tôi là bác sĩ Nguyễn gọi.","note":"Câu mở đầu điện thoại công việc"},{"id":"daily-phone-002","en":"Could I speak to Dr. Smith, please?","vn":"Tôi có thể nói chuyện với bác sĩ Smith không?","note":""},{"id":"daily-phone-003","en":"I''m sorry, could you speak a bit louder? The line isn''t great.","vn":"Xin lỗi, bạn có thể nói to hơn một chút không? Đường truyền không tốt lắm.","note":""},{"id":"daily-phone-004","en":"Sorry, I didn''t catch that. Could you repeat?","vn":"Xin lỗi, tôi không nghe rõ. Bạn có thể nói lại không?","note":"Câu quan trọng! Đừng ngại dùng."},{"id":"daily-phone-005","en":"I''d like to make an appointment for next Tuesday.","vn":"Tôi muốn đặt lịch hẹn vào thứ Ba tuần tới.","note":""},{"id":"daily-phone-006","en":"Could we reschedule our meeting? Something''s come up.","vn":"Chúng ta có thể đổi lịch họp không? Có việc đột xuất.","note":"reschedule = đổi lịch; something came up = có việc đột xuất"},{"id":"daily-phone-007","en":"What time works best for you?","vn":"Thời gian nào phù hợp nhất với bạn?","note":""},{"id":"daily-phone-008","en":"Would 3 pm on Thursday work?","vn":"3 giờ chiều thứ Năm có được không?","note":""},{"id":"daily-phone-009","en":"Could you send me a calendar invite?","vn":"Bạn có thể gửi cho tôi lời mời lịch không?","note":"calendar invite = lời mời trên lịch"},{"id":"daily-phone-010","en":"I''ll have to get back to you on that.","vn":"Tôi sẽ phải trả lời bạn sau về vấn đề đó.","note":"get back to someone = liên hệ lại"},{"id":"daily-phone-011","en":"Let me check my schedule and confirm.","vn":"Để tôi kiểm tra lịch và xác nhận.","note":""},{"id":"daily-phone-012","en":"I''m afraid I have to cancel our appointment.","vn":"Tôi e rằng phải hủy cuộc hẹn của chúng ta.","note":"I''m afraid = tiếc rằng (lịch sự)"}]', '[{"id":"daily-phone-vocab-1","word":"reschedule","phonetic":"/ˌriːˈʃedjuːl/","meaning":"đổi lịch, dời lịch"},{"id":"daily-phone-vocab-2","word":"get back to","phonetic":"/ɡet bæk tuː/","meaning":"liên hệ lại, trả lời sau"},{"id":"daily-phone-vocab-3","word":"calendar invite","phonetic":"","meaning":"lời mời lịch điện tử"},{"id":"daily-phone-vocab-4","word":"pass the message","phonetic":"","meaning":"chuyển lời nhắn"},{"id":"daily-phone-vocab-5","word":"confirm","phonetic":"/kənˈfɜːrm/","meaning":"xác nhận"}]', '["Bắt đầu điện thoại: ''This is [name]'' (không nói ''I am [name]'').","Khi không nghe rõ: ''I''m sorry, you''re breaking up'' = tín hiệu bị gián đoạn.","Khi nhắn lại: ''Could you ask them to call me back?'' — nhờ gọi lại."]', '[{"id":"daily-phone-dial-1","speaker":"Receptionist","en":"Good afternoon, St. James Clinic. How can I help?","vn":"Chào buổi chiều, Phòng khám St. James. Tôi có thể giúp gì?"},{"id":"daily-phone-dial-2","speaker":"You","en":"Hello, this is Dr. Nguyen. I''d like to speak with Dr. Collins if she''s available.","vn":"Xin chào, đây là bác sĩ Nguyễn. Tôi muốn nói chuyện với bác sĩ Collins nếu bà ấy rảnh."},{"id":"daily-phone-dial-3","speaker":"Receptionist","en":"She''s with a patient right now. Can I take a message?","vn":"Bà ấy đang với bệnh nhân. Tôi có thể nhắn tin lại không?"},{"id":"daily-phone-dial-4","speaker":"You","en":"Yes please. Could you let her know I called about the ENT conference next month?","vn":"Vâng. Bạn có thể nhắn với bà ấy rằng tôi gọi về hội nghị TMH tháng tới không?"},{"id":"daily-phone-dial-5","speaker":"Receptionist","en":"Of course. Does she have your number?","vn":"Dĩ nhiên. Bà ấy có số của bạn không?"},{"id":"daily-phone-dial-6","speaker":"You","en":"She should, but just in case it''s 0912-345-678.","vn":"Bà ấy nên có, nhưng phòng hờ thì là 0912-345-678."},{"id":"daily-phone-dial-7","speaker":"Receptionist","en":"Got it. I''ll pass the message along.","vn":"Ghi rồi. Tôi sẽ chuyển lời nhắn."}]', 6, true),
('airport', 'At the Airport', 'Ở Sân Bay', '✈️', '#0369a1', '12 phrases · 5 vocab items', '[{"id":"daily-airport-001","en":"Could you tell me where the check-in counter for Singapore Airlines is?","vn":"Bạn có thể chỉ cho tôi quầy check-in của Singapore Airlines ở đâu không?","note":""},{"id":"daily-airport-002","en":"I''d prefer a window seat, please.","vn":"Tôi muốn ngồi ghế cạnh cửa sổ.","note":"window / middle / aisle seat"},{"id":"daily-airport-003","en":"Is my flight on time?","vn":"Chuyến bay của tôi có đúng giờ không?","note":""},{"id":"daily-airport-004","en":"My flight has been delayed. Is there another option?","vn":"Chuyến bay của tôi bị hoãn. Có lựa chọn nào khác không?","note":""},{"id":"daily-airport-005","en":"I need to make my connecting flight in Singapore.","vn":"Tôi cần kịp chuyến bay nối ở Singapore.","note":"connecting flight = chuyến bay nối"},{"id":"daily-airport-006","en":"My luggage is overweight. What''s the excess baggage fee?","vn":"Hành lý của tôi bị quá cân. Phí hành lý thêm là bao nhiêu?","note":""},{"id":"daily-airport-007","en":"Where is gate C12?","vn":"Cửa ra máy bay C12 ở đâu?","note":""},{"id":"daily-airport-008","en":"Could I get a transit hotel voucher?","vn":"Tôi có thể nhận voucher khách sạn quá cảnh không?","note":"transit = quá cảnh"},{"id":"daily-airport-009","en":"Could I request a wheelchair for my patient?","vn":"Tôi có thể yêu cầu xe lăn cho bệnh nhân của tôi không?","note":""},{"id":"daily-airport-010","en":"Do I need to re-check my bags for the connecting flight?","vn":"Tôi có cần check lại hành lý cho chuyến bay nối không?","note":""},{"id":"daily-airport-011","en":"Where is the duty-free shopping area?","vn":"Khu mua sắm miễn thuế ở đâu?","note":"duty-free = hàng miễn thuế"},{"id":"daily-airport-012","en":"What''s the Wi-Fi password for the lounge?","vn":"Mật khẩu Wi-Fi của phòng chờ là gì?","note":""}]', '[{"id":"daily-airport-vocab-1","word":"connecting flight","phonetic":"/kəˈnektɪŋ flaɪt/","meaning":"chuyến bay nối"},{"id":"daily-airport-vocab-2","word":"transit","phonetic":"/ˈtrænsɪt/","meaning":"quá cảnh"},{"id":"daily-airport-vocab-3","word":"duty-free","phonetic":"/ˌdjuːti ˈfriː/","meaning":"hàng miễn thuế"},{"id":"daily-airport-vocab-4","word":"overweight","phonetic":"/ˌoʊvərˈweɪt/","meaning":"quá cân (hành lý)"},{"id":"daily-airport-vocab-5","word":"boarding","phonetic":"/ˈbɔːrdɪŋ/","meaning":"lên máy bay"}]', '["Luôn hỏi về connecting flight khi check-in — nhân viên sẽ ghi chú để ưu tiên.","Nếu chuyến bay bị hủy: yêu cầu ''meal voucher'' và ''accommodation voucher'' nếu delay qua đêm.","Phòng chờ (lounge): với thẻ tín dụng Premium hoặc thẻ Priority Pass, bạn thường vào miễn phí."]', '[{"id":"daily-airport-dial-1","speaker":"Agent","en":"Good morning! Passport and ticket please.","vn":"Chào buổi sáng! Cho tôi hộ chiếu và vé."},{"id":"daily-airport-dial-2","speaker":"You","en":"Here you go. I''d like a window seat if possible.","vn":"Đây nhé. Tôi muốn ghế cửa sổ nếu được."},{"id":"daily-airport-dial-3","speaker":"Agent","en":"Let me check. Yes, 22A is available. That''s a window seat.","vn":"Để tôi kiểm tra. Vâng, 22A còn trống. Đó là ghế cửa sổ."},{"id":"daily-airport-dial-4","speaker":"You","en":"Perfect. Is the flight on time?","vn":"Tuyệt vời. Chuyến bay có đúng giờ không?"},{"id":"daily-airport-dial-5","speaker":"Agent","en":"There''s a 30-minute delay due to air traffic. Boarding starts at 10:15.","vn":"Trễ 30 phút do kiểm soát không lưu. Boarding bắt đầu lúc 10:15."},{"id":"daily-airport-dial-6","speaker":"You","en":"I have a connecting flight in Singapore at 2pm. Will I still make it?","vn":"Tôi có chuyến bay nối ở Singapore lúc 2 giờ chiều. Tôi có kịp không?"},{"id":"daily-airport-dial-7","speaker":"Agent","en":"That should be fine. The connection is about 3 hours so you''ll have time.","vn":"Nên ổn. Thời gian transit khoảng 3 tiếng nên bạn có đủ thời gian."}]', 7, true),
('social', 'Expressing Opinions & Feelings', 'Bày tỏ ý kiến & Cảm xúc', '🗣️', '#be185d', '12 phrases · 5 vocab items', '[{"id":"daily-social-001","en":"In my opinion, this approach works better because...","vn":"Theo ý kiến của tôi, cách này hiệu quả hơn vì...","note":""},{"id":"daily-social-002","en":"That''s a good point, but I see it slightly differently.","vn":"Đó là điểm hay, nhưng tôi thấy hơi khác một chút.","note":"Cách phản bác lịch sự"},{"id":"daily-social-003","en":"I completely agree with you on that.","vn":"Tôi hoàn toàn đồng ý với bạn về điều đó.","note":""},{"id":"daily-social-004","en":"I''m not sure I agree — could you explain more?","vn":"Tôi không chắc đồng ý — bạn có thể giải thích thêm không?","note":""},{"id":"daily-social-005","en":"To be honest, I''m not really a fan of that idea.","vn":"Thật ra, tôi không mấy hứng thú với ý tưởng đó.","note":"to be honest = thật ra, nói thật"},{"id":"daily-social-006","en":"That''s fascinating! I hadn''t thought of it that way.","vn":"Thú vị thật! Tôi chưa nghĩ theo hướng đó.","note":""},{"id":"daily-social-007","en":"I''m really impressed by how they managed that.","vn":"Tôi thực sự ấn tượng với cách họ xử lý điều đó.","note":""},{"id":"daily-social-008","en":"Honestly, I''m a bit overwhelmed at the moment.","vn":"Thật ra, tôi đang hơi bị quá tải lúc này.","note":"overwhelmed = quá tải, ngập đầu"},{"id":"daily-social-009","en":"I couldn''t agree more — that''s exactly how I feel.","vn":"Tôi đồng ý hoàn toàn — đó chính xác là cảm giác của tôi.","note":""},{"id":"daily-social-010","en":"Let me think about that for a moment.","vn":"Để tôi suy nghĩ một chút.","note":"Câu hay để câu giờ khi cần nghĩ"},{"id":"daily-social-011","en":"I see where you''re coming from.","vn":"Tôi hiểu ý bạn nói.","note":"Thể hiện bạn đang nghe và hiểu"},{"id":"daily-social-012","en":"Fair enough — you make a valid point.","vn":"Có lý đó — bạn đưa ra quan điểm xác đáng.","note":"fair enough = có lý"}]', '[{"id":"daily-social-vocab-1","word":"overwhelmed","phonetic":"/ˌoʊvərˈwelmd/","meaning":"quá tải, ngập đầu"},{"id":"daily-social-vocab-2","word":"fair enough","phonetic":"/feər ɪˈnʌf/","meaning":"có lý, được thôi"},{"id":"daily-social-vocab-3","word":"valid","phonetic":"/ˈvælɪd/","meaning":"hợp lệ, xác đáng"},{"id":"daily-social-vocab-4","word":"potential","phonetic":"/pəˈtenʃəl/","meaning":"tiềm năng"},{"id":"daily-social-vocab-5","word":"fascinating","phonetic":"/ˈfæsɪneɪtɪŋ/","meaning":"hấp dẫn, thú vị"}]', '["Khi không đồng ý: bắt đầu bằng ''I see your point, but...'' — thể hiện bạn đã nghe đối phương.","''Let me think about that'' = câu câu giờ rất tự nhiên, không có gì sai khi nói câu này.","Thêm ''actually'' để nhấn mạnh: ''I actually really liked it!'' — thực ra tôi rất thích nó!"]', '[{"id":"daily-social-dial-1","speaker":"Colleague","en":"What did you think of the new hospital management system?","vn":"Bạn nghĩ gì về hệ thống quản lý bệnh viện mới?"},{"id":"daily-social-dial-2","speaker":"You","en":"To be honest, I think it has potential, but the interface is quite complex.","vn":"Thật ra, tôi nghĩ nó có tiềm năng, nhưng giao diện khá phức tạp."},{"id":"daily-social-dial-3","speaker":"Colleague","en":"I completely agree. It took me a week just to learn the basics.","vn":"Tôi hoàn toàn đồng ý. Tôi mất cả tuần chỉ để học cơ bản."},{"id":"daily-social-dial-4","speaker":"You","en":"That said, the patient records section is actually very well designed.","vn":"Tuy nhiên, phần hồ sơ bệnh nhân thực sự được thiết kế rất tốt."},{"id":"daily-social-dial-5","speaker":"Colleague","en":"Fair enough. I guess it''s just a matter of getting used to it.","vn":"Có lý đó. Tôi đoán chỉ là vấn đề làm quen thôi."}]', 8, true),
('plans', 'Making Plans & Invitations', 'Lên kế hoạch & Mời mọc', '📅', '#0f766e', '12 phrases · 5 vocab items', '[{"id":"daily-plans-001","en":"Are you free this weekend?","vn":"Cuối tuần này bạn rảnh không?","note":""},{"id":"daily-plans-002","en":"Would you like to grab dinner after the conference?","vn":"Bạn có muốn ăn tối sau hội nghị không?","note":"grab = rủ đi (thân mật)"},{"id":"daily-plans-003","en":"I was wondering if you''d like to join us for drinks?","vn":"Tôi tự hỏi liệu bạn có muốn cùng chúng tôi đi uống không?","note":"Cách mời lịch sự, ít áp lực hơn"},{"id":"daily-plans-004","en":"That sounds great! What time were you thinking?","vn":"Nghe hay đó! Bạn nghĩ khoảng mấy giờ?","note":""},{"id":"daily-plans-005","en":"I''d love to, but I have a prior commitment.","vn":"Tôi rất muốn, nhưng tôi có việc đã hẹn trước.","note":"prior commitment = việc đã có trước"},{"id":"daily-plans-006","en":"Could we do it another time? I''m swamped this week.","vn":"Chúng ta có thể làm lần khác không? Tuần này tôi kẹt lắm.","note":"swamped = ngập đầu công việc"},{"id":"daily-plans-007","en":"Let me check and get back to you.","vn":"Để tôi kiểm tra rồi trả lời bạn sau.","note":""},{"id":"daily-plans-008","en":"Count me in!","vn":"Tính tôi vào!","note":"count me in = tôi tham gia"},{"id":"daily-plans-009","en":"I''ll have to take a rain check on that.","vn":"Tôi phải hoãn lại lần này.","note":"rain check = hẹn lại lần khác (thành ngữ Mỹ)"},{"id":"daily-plans-010","en":"Do you want to split a cab to the restaurant?","vn":"Bạn có muốn đi chung taxi đến nhà hàng không?","note":"split a cab = đi chung taxi chia tiền"},{"id":"daily-plans-011","en":"It''s my treat tonight.","vn":"Tối nay tôi mời.","note":"my treat = tôi mời (trả tiền)"},{"id":"daily-plans-012","en":"Dutch? We''ll split the bill.","vn":"Chia đôi nhé? Chúng ta chia tiền.","note":"go Dutch = chia tiền"}]', '[{"id":"daily-plans-vocab-1","word":"prior commitment","phonetic":"/ˈpraɪər kəˈmɪtmənt/","meaning":"việc đã hẹn trước"},{"id":"daily-plans-vocab-2","word":"swamped","phonetic":"/swɒmpt/","meaning":"ngập đầu công việc"},{"id":"daily-plans-vocab-3","word":"rain check","phonetic":"/reɪn tʃek/","meaning":"hẹn lại lần khác"},{"id":"daily-plans-vocab-4","word":"count me in","phonetic":"/kaʊnt miː ɪn/","meaning":"tính tôi vào, tôi đồng ý tham gia"},{"id":"daily-plans-vocab-5","word":"my treat","phonetic":"/maɪ triːt/","meaning":"tôi mời, tôi trả tiền"}]', '["''I''ll have to take a rain check'' = từ chối lịch sự, ngụ ý muốn hẹn lần khác.","''Count me in!'' = câu nhiệt tình, tự nhiên khi đồng ý tham gia.","Từ chối lịch sự: luôn có ''I''d love to, but...'' trước khi nêu lý do."]', '[{"id":"daily-plans-dial-1","speaker":"Colleague","en":"A few of us are going to that new seafood place tonight. Want to join?","vn":"Một số chúng tôi đang đến nhà hàng hải sản mới tối nay. Bạn muốn đi không?"},{"id":"daily-plans-dial-2","speaker":"You","en":"That sounds amazing! What time?","vn":"Nghe hấp dẫn quá! Mấy giờ vậy?"},{"id":"daily-plans-dial-3","speaker":"Colleague","en":"We''re heading there around 7:30. Meet at the hotel lobby?","vn":"Chúng tôi đi khoảng 7:30. Gặp nhau ở sảnh khách sạn nhé?"},{"id":"daily-plans-dial-4","speaker":"You","en":"Perfect. Just so you know, I''m allergic to shellfish.","vn":"Tuyệt. Bạn biết đấy, tôi dị ứng hải sản có vỏ."},{"id":"daily-plans-dial-5","speaker":"Colleague","en":"Good to know! They have plenty of other options too.","vn":"Tốt là biết trước! Họ có nhiều lựa chọn khác nữa."},{"id":"daily-plans-dial-6","speaker":"You","en":"Great. Should we split a cab? It might be faster.","vn":"Tốt. Chúng ta đi chung taxi không? Có thể nhanh hơn."},{"id":"daily-plans-dial-7","speaker":"Colleague","en":"Good idea. See you at 7:15 then!","vn":"Ý hay đó. Hẹn gặp lúc 7:15 nhé!"}]', 9, true),
('problems', 'Handling Problems & Complaints', 'Xử lý vấn đề & Phàn nàn', '⚠️', '#b45309', '12 phrases · 5 vocab items', '[{"id":"daily-problems-001","en":"Excuse me, I think there''s been a mistake with my order.","vn":"Xin lỗi, tôi nghĩ có sự nhầm lẫn với đơn của tôi.","note":""},{"id":"daily-problems-002","en":"I''m not happy with the service I received today.","vn":"Tôi không hài lòng với dịch vụ hôm nay.","note":"Câu phàn nàn nhẹ nhàng"},{"id":"daily-problems-003","en":"I''d like to speak with the manager, please.","vn":"Tôi muốn nói chuyện với quản lý.","note":""},{"id":"daily-problems-004","en":"This isn''t what I was told. I was promised that...","vn":"Đây không phải những gì tôi được nói. Tôi được hứa rằng...","note":""},{"id":"daily-problems-005","en":"Could you help me resolve this issue?","vn":"Bạn có thể giúp tôi giải quyết vấn đề này không?","note":""},{"id":"daily-problems-006","en":"I was overcharged. The menu says $15 but I was charged $20.","vn":"Tôi bị tính tiền sai. Menu ghi 15$ nhưng tôi bị tính 20$.","note":""},{"id":"daily-problems-007","en":"I''d like a refund, please.","vn":"Tôi muốn được hoàn tiền.","note":"refund = hoàn tiền"},{"id":"daily-problems-008","en":"There''s been a mix-up with my booking.","vn":"Có sự nhầm lẫn với đặt chỗ của tôi.","note":"mix-up = nhầm lẫn"},{"id":"daily-problems-009","en":"I understand you''re busy, but this has been going on for a while.","vn":"Tôi hiểu bạn đang bận, nhưng vấn đề này đã kéo dài một lúc rồi.","note":""},{"id":"daily-problems-010","en":"I appreciate your help in sorting this out.","vn":"Tôi đánh giá cao sự giúp đỡ của bạn trong việc giải quyết điều này.","note":"sorting out = giải quyết, sắp xếp"},{"id":"daily-problems-011","en":"Could I have that in writing?","vn":"Tôi có thể có điều đó bằng văn bản không?","note":""},{"id":"daily-problems-012","en":"I''ll follow up with an email.","vn":"Tôi sẽ theo dõi bằng email.","note":""}]', '[{"id":"daily-problems-vocab-1","word":"refund","phonetic":"/ˈriːfʌnd/","meaning":"hoàn tiền"},{"id":"daily-problems-vocab-2","word":"overcharged","phonetic":"/ˌoʊvərˈtʃɑːrdʒd/","meaning":"bị tính tiền quá nhiều"},{"id":"daily-problems-vocab-3","word":"mix-up","phonetic":"/ˈmɪksʌp/","meaning":"nhầm lẫn"},{"id":"daily-problems-vocab-4","word":"sort out","phonetic":"/sɔːrt aʊt/","meaning":"giải quyết, sắp xếp"},{"id":"daily-problems-vocab-5","word":"in writing","phonetic":"/ɪn ˈraɪtɪŋ/","meaning":"bằng văn bản"}]', '["Khi phàn nàn: giữ giọng bình tĩnh, rõ ràng — không tức giận sẽ được giải quyết nhanh hơn.","Luôn có bằng chứng: booking confirmation, hóa đơn cũ, ảnh chụp.","Câu kết hiệu quả: ''What can you do for me?'' — Bạn có thể làm gì cho tôi?"]', '[{"id":"daily-problems-dial-1","speaker":"You","en":"Excuse me, I think there''s been an issue with my hotel room charge.","vn":"Xin lỗi, tôi nghĩ có vấn đề với phí phòng khách sạn của tôi."},{"id":"daily-problems-dial-2","speaker":"Manager","en":"I''m sorry to hear that. Could you tell me what happened?","vn":"Tôi rất tiếc khi nghe điều đó. Bạn có thể cho tôi biết chuyện gì xảy ra không?"},{"id":"daily-problems-dial-3","speaker":"You","en":"I booked a standard room but was charged for a suite. The difference is $150.","vn":"Tôi đặt phòng tiêu chuẩn nhưng bị tính tiền phòng suite. Chênh lệch là 150$."},{"id":"daily-problems-dial-4","speaker":"Manager","en":"Let me look into that for you right away. Could I have your room number?","vn":"Để tôi xem ngay. Cho tôi số phòng của bạn được không?"},{"id":"daily-problems-dial-5","speaker":"You","en":"Room 1402. I also have the original booking confirmation here.","vn":"Phòng 1402. Tôi cũng có xác nhận đặt phòng gốc ở đây."},{"id":"daily-problems-dial-6","speaker":"Manager","en":"You''re absolutely right. I do apologize — we''ll adjust the bill immediately.","vn":"Bạn hoàn toàn đúng. Tôi xin lỗi — chúng tôi sẽ điều chỉnh hóa đơn ngay."},{"id":"daily-problems-dial-7","speaker":"You","en":"Thank you. Could I have a revised receipt?","vn":"Cảm ơn. Tôi có thể nhận hóa đơn đã sửa không?"}]', 10, true),
('clarification', 'When You Don''t Understand', 'Khi chưa hiểu / Hỏi lại', '🤔', '#6d28d9', '12 phrases · 5 vocab items', '[{"id":"daily-clarification-001","en":"Sorry, I didn''t quite catch that. Could you repeat?","vn":"Xin lỗi, tôi không bắt kịp. Bạn có thể nói lại không?","note":"CÂU QUAN TRỌNG NHẤT — dùng tự tin!"},{"id":"daily-clarification-002","en":"Could you slow down a little? My English is still improving.","vn":"Bạn có thể nói chậm hơn không? Tiếng Anh của tôi vẫn đang cải thiện.","note":""},{"id":"daily-clarification-003","en":"I''m sorry, could you say that in a different way?","vn":"Xin lỗi, bạn có thể diễn đạt theo cách khác không?","note":""},{"id":"daily-clarification-004","en":"Could you spell that out for me?","vn":"Bạn có thể đánh vần cho tôi không?","note":"Khi không nghe rõ tên/từ lạ"},{"id":"daily-clarification-005","en":"What does [word] mean exactly?","vn":"[từ] có nghĩa chính xác là gì?","note":""},{"id":"daily-clarification-006","en":"So if I understand correctly, you''re saying that...","vn":"Vậy nếu tôi hiểu đúng, bạn đang nói rằng...","note":"Xác nhận lại ý hiểu — rất chuyên nghiệp"},{"id":"daily-clarification-007","en":"Let me make sure I understand — you mean...?","vn":"Để tôi chắc chắn tôi hiểu — ý bạn là...?","note":""},{"id":"daily-clarification-008","en":"Could you write that down? I want to make sure I get it right.","vn":"Bạn có thể viết ra không? Tôi muốn đảm bảo hiểu đúng.","note":""},{"id":"daily-clarification-009","en":"Sorry — the line is a bit unclear. Could you repeat that?","vn":"Xin lỗi — đường dây hơi không rõ. Bạn có thể nói lại không?","note":"Dùng qua điện thoại"},{"id":"daily-clarification-010","en":"I think I understand, but let me confirm — you said [X], right?","vn":"Tôi nghĩ tôi hiểu, nhưng để tôi xác nhận — bạn nói [X], đúng không?","note":""},{"id":"daily-clarification-011","en":"Bear with me — I''m still thinking of the right word.","vn":"Chịu khó đợi tôi một chút — tôi vẫn đang nghĩ từ phù hợp.","note":"bear with me = kiên nhẫn với tôi"},{"id":"daily-clarification-012","en":"Excuse my English — I''m still learning.","vn":"Xin lỗi vì tiếng Anh của tôi — tôi vẫn đang học.","note":"Câu tự tin và chân thành"}]', '[{"id":"daily-clarification-vocab-1","word":"bear with me","phonetic":"/beər wɪð miː/","meaning":"kiên nhẫn với tôi, chịu đợi"},{"id":"daily-clarification-vocab-2","word":"clarify","phonetic":"/ˈklærɪfaɪ/","meaning":"làm rõ, giải thích rõ"},{"id":"daily-clarification-vocab-3","word":"aetiology","phonetic":"/ˌiːtiˈɒlədʒi/","meaning":"căn nguyên (nguyên nhân bệnh)"},{"id":"daily-clarification-vocab-4","word":"paraphrase","phonetic":"/ˈpærəfreɪz/","meaning":"diễn đạt lại bằng lời khác"},{"id":"daily-clarification-vocab-5","word":"confirm","phonetic":"/kənˈfɜːrm/","meaning":"xác nhận"}]', '["ĐỪNG GIẢ VỜ HIỂU — hỏi lại là dấu hiệu của người thông minh, không phải yếu kém.","Kỹ thuật hay: lặp lại những gì nghe được ''So you mean... ?'' để kiểm tra xem có đúng không.","''Excuse my English'' là câu tự tin và chân thành — người bản xứ sẽ trân trọng điều này."]', '[{"id":"daily-clarification-dial-1","speaker":"Colleague","en":"So for the case presentation, you''ll need to include the aetiology and pathophysiology.","vn":"Vậy để trình bày ca, bạn cần bao gồm căn nguyên và sinh lý bệnh học."},{"id":"daily-clarification-dial-2","speaker":"You","en":"Sorry — could you say that again? I''m not sure I caught the second part.","vn":"Xin lỗi — bạn có thể nói lại không? Tôi không chắc mình nghe rõ phần thứ hai."},{"id":"daily-clarification-dial-3","speaker":"Colleague","en":"Of course. I said aetiology — which is the cause — and pathophysiology.","vn":"Dĩ nhiên. Tôi nói căn nguyên — là nguyên nhân — và sinh lý bệnh học."},{"id":"daily-clarification-dial-4","speaker":"You","en":"I see. So if I understand correctly, you mean the cause and the disease mechanism?","vn":"Tôi hiểu rồi. Vậy nếu tôi hiểu đúng, bạn muốn nói nguyên nhân và cơ chế bệnh?"},{"id":"daily-clarification-dial-5","speaker":"Colleague","en":"Exactly right! Your understanding is perfect.","vn":"Chính xác! Bạn hiểu rất tốt."},{"id":"daily-clarification-dial-6","speaker":"You","en":"Thank you. Bear with me — I''m still getting used to the medical terminology in English.","vn":"Cảm ơn. Chịu khó đợi tôi — tôi vẫn đang làm quen với thuật ngữ y khoa bằng tiếng Anh."}]', 11, true);
insert into medical_sections (section_type, slug, title, subtitle, phrases, sort_order, published) values
('consultation', 'consultation-greeting', '👋 Chào hỏi', 'Khung câu hỏi cho khám bệnh và khai thác triệu chứng.', '[{"id":"med-consult-greeting-001","en":"Good morning! Please come in and have a seat.","vn":"Chào buổi sáng! Mời vào và ngồi đây.","note":""},{"id":"med-consult-greeting-002","en":"Hello, I''m Dr. [Your name]. How can I help you today?","vn":"Xin chào, tôi là bác sĩ [Tên]. Hôm nay bạn cần khám gì?","note":""},{"id":"med-consult-greeting-003","en":"What brings you here today?","vn":"Hôm nay bạn đến vì vấn đề gì?","note":"Câu hỏi mở, thường dùng nhất khi bắt đầu khám."},{"id":"med-consult-greeting-004","en":"How long have you had this problem?","vn":"Vấn đề này đã được bao lâu rồi?","note":""},{"id":"med-consult-greeting-005","en":"Is this the first time you''ve experienced this?","vn":"Đây có phải lần đầu bạn bị như vậy không?","note":""},{"id":"med-consult-greeting-006","en":"Please describe your symptoms.","vn":"Hãy mô tả các triệu chứng của bạn.","note":""}]', 0, true),
('consultation', 'consultation-ear', '👂 Khám Tai', 'Khung câu hỏi cho khám bệnh và khai thác triệu chứng.', '[{"id":"med-consult-ear-001","en":"Do you have any ear pain?","vn":"Bạn có đau tai không?","note":""},{"id":"med-consult-ear-002","en":"Are you experiencing any hearing loss?","vn":"Bạn có bị giảm thính lực không?","note":""},{"id":"med-consult-ear-003","en":"Do you have any ringing in your ears?","vn":"Bạn có bị ù tai không?","note":"Ringing in ears = tinnitus /ˈtɪnɪtəs/"},{"id":"med-consult-ear-004","en":"Is there any discharge coming from your ear?","vn":"Có dịch chảy ra từ tai không?","note":"discharge = dịch tiết"},{"id":"med-consult-ear-005","en":"Do you feel dizzy or have problems with balance?","vn":"Bạn có chóng mặt hoặc mất thăng bằng không?","note":"dizzy = chóng mặt, balance = thăng bằng"},{"id":"med-consult-ear-006","en":"I''m going to examine your ear now. Please hold still.","vn":"Tôi sẽ khám tai cho bạn bây giờ. Vui lòng giữ yên.","note":""},{"id":"med-consult-ear-007","en":"I can see some earwax buildup. That''s likely causing the problem.","vn":"Tôi thấy có ráy tai tích tụ. Đó có thể là nguyên nhân.","note":"earwax buildup = ráy tai tích tụ"},{"id":"med-consult-ear-008","en":"Your eardrum looks normal.","vn":"Màng nhĩ của bạn trông bình thường.","note":"eardrum = màng nhĩ"},{"id":"med-consult-ear-009","en":"There appears to be a foreign object in your ear.","vn":"Có vẻ có dị vật trong tai bạn.","note":"foreign object = dị vật"}]', 1, true),
('consultation', 'consultation-nose', '👃 Khám Mũi', 'Khung câu hỏi cho khám bệnh và khai thác triệu chứng.', '[{"id":"med-consult-nose-001","en":"Do you have a stuffy or blocked nose?","vn":"Bạn có nghẹt mũi không?","note":"stuffy/blocked nose = nghẹt mũi"},{"id":"med-consult-nose-002","en":"Are you experiencing any nasal discharge? What color is it?","vn":"Bạn có chảy nước mũi không? Màu gì?","note":"nasal discharge = nước mũi chảy"},{"id":"med-consult-nose-003","en":"Do you have frequent nosebleeds?","vn":"Bạn có hay bị chảy máu mũi không?","note":"nosebleed = chảy máu cam"},{"id":"med-consult-nose-004","en":"Have you lost your sense of smell?","vn":"Bạn có mất mùi không?","note":"sense of smell = khứu giác"},{"id":"med-consult-nose-005","en":"Do you have any allergies?","vn":"Bạn có bị dị ứng gì không?","note":""},{"id":"med-consult-nose-006","en":"Has your nose been injured before?","vn":"Mũi bạn đã từng bị chấn thương chưa?","note":""},{"id":"med-consult-nose-007","en":"I''m going to spray some decongestant into your nose before the examination.","vn":"Tôi sẽ xịt thuốc co mạch vào mũi trước khi khám.","note":"decongestant = thuốc co mạch/thông mũi"}]', 2, true),
('consultation', 'consultation-throat', '🗣️ Khám Họng', 'Khung câu hỏi cho khám bệnh và khai thác triệu chứng.', '[{"id":"med-consult-throat-001","en":"Do you have a sore throat?","vn":"Bạn có đau họng không?","note":""},{"id":"med-consult-throat-002","en":"How long have you had trouble swallowing?","vn":"Bạn bị khó nuốt được bao lâu rồi?","note":"swallowing = nuốt"},{"id":"med-consult-throat-003","en":"Do you have a hoarse voice?","vn":"Bạn có bị khàn tiếng không?","note":"hoarse = khàn giọng"},{"id":"med-consult-throat-004","en":"Please open your mouth and say ''Ahh''.","vn":"Mở miệng ra và nói ''Ahh''.","note":"Câu dùng khi khám họng"},{"id":"med-consult-throat-005","en":"Your tonsils are swollen.","vn":"Amidan của bạn đang sưng.","note":"tonsils = amidan"},{"id":"med-consult-throat-006","en":"I can see some redness and swelling in your throat.","vn":"Tôi thấy có vùng đỏ và sưng trong họng bạn.","note":""}]', 3, true),
('consultation', 'consultation-diagnosis', '🔍 Chẩn Đoán & Kế Hoạch', 'Khung câu hỏi cho khám bệnh và khai thác triệu chứng.', '[{"id":"med-consult-diagnosis-001","en":"Based on my examination, you have a middle ear infection.","vn":"Dựa trên khám bệnh, bạn bị viêm tai giữa.","note":"middle ear infection = viêm tai giữa"},{"id":"med-consult-diagnosis-002","en":"You have sinusitis — inflammation of the sinuses.","vn":"Bạn bị viêm xoang.","note":"sinusitis = viêm xoang"},{"id":"med-consult-diagnosis-003","en":"I''d like to do a nasal endoscopy to get a better look.","vn":"Tôi muốn làm nội soi mũi để xem rõ hơn.","note":"endoscopy = nội soi"},{"id":"med-consult-diagnosis-004","en":"I''m going to prescribe some antibiotics for you.","vn":"Tôi sẽ kê kháng sinh cho bạn.","note":"prescribe = kê toa, antibiotics = kháng sinh"},{"id":"med-consult-diagnosis-005","en":"Please come back in one week if it doesn''t improve.","vn":"Nếu không cải thiện, vui lòng tái khám sau một tuần.","note":""},{"id":"med-consult-diagnosis-006","en":"Do you have any questions for me?","vn":"Bạn có câu hỏi gì cho tôi không?","note":"Luôn hỏi câu này trước khi kết thúc khám."},{"id":"med-consult-diagnosis-007","en":"I''ll refer you to a specialist.","vn":"Tôi sẽ giới thiệu bạn đến bác sĩ chuyên khoa.","note":"refer = giới thiệu, specialist = bác sĩ chuyên khoa"}]', 4, true),
('conference', 'conference-presentation', '📊 Trình Bày Ca', 'Ngôn ngữ hội nghị và giao tiếp chuyên môn.', '[{"id":"med-conf-presentation-001","en":"Good morning everyone. I''d like to present an interesting case.","vn":"Chào buổi sáng mọi người. Tôi muốn trình bày một ca thú vị.","note":""},{"id":"med-conf-presentation-002","en":"The patient is a 45-year-old male presenting with a 3-week history of hearing loss.","vn":"Bệnh nhân nam 45 tuổi, bệnh sử 3 tuần giảm thính lực.","note":""},{"id":"med-conf-presentation-003","en":"On examination, we found significant cerumen impaction bilaterally.","vn":"Khi khám, chúng tôi thấy ráy tai tắc nghẽn 2 bên.","note":"cerumen impaction = ráy tai tắc; bilateral = 2 bên"},{"id":"med-conf-presentation-004","en":"The CT scan revealed opacification of the right maxillary sinus.","vn":"CT scan cho thấy mờ đục xoang hàm phải.","note":"maxillary sinus = xoang hàm"},{"id":"med-conf-presentation-005","en":"After treatment, the patient showed significant improvement.","vn":"Sau điều trị, bệnh nhân cải thiện đáng kể.","note":""},{"id":"med-conf-presentation-006","en":"In conclusion, this case highlights the importance of early diagnosis.","vn":"Kết luận, ca này nhấn mạnh tầm quan trọng của chẩn đoán sớm.","note":""},{"id":"med-conf-presentation-007","en":"I''d be happy to take any questions.","vn":"Tôi sẵn sàng nhận câu hỏi.","note":""}]', 100, true),
('conference', 'conference-networking', '🤝 Networking', 'Ngôn ngữ hội nghị và giao tiếp chuyên môn.', '[{"id":"med-conf-networking-001","en":"Your presentation was very insightful. I have a similar experience in my practice.","vn":"Bài trình bày của bạn rất sâu sắc. Tôi có kinh nghiệm tương tự trong thực hành.","note":""},{"id":"med-conf-networking-002","en":"Could we exchange contact details? I''d love to collaborate.","vn":"Chúng ta có thể trao đổi thông tin liên hệ không? Tôi muốn hợp tác.","note":""},{"id":"med-conf-networking-003","en":"Which hospital do you work at?","vn":"Bạn làm ở bệnh viện nào?","note":""},{"id":"med-conf-networking-004","en":"Have you published any papers on this topic?","vn":"Bạn có đăng bài về chủ đề này chưa?","note":"paper = bài báo khoa học"},{"id":"med-conf-networking-005","en":"What''s your approach to difficult cases like this?","vn":"Cách tiếp cận của bạn với các ca khó như thế này là gì?","note":""},{"id":"med-conf-networking-006","en":"We use a slightly different protocol in Vietnam. Let me tell you about it.","vn":"Ở Việt Nam chúng tôi dùng phác đồ hơi khác. Để tôi kể cho bạn nghe.","note":""}]', 101, true),
('conference', 'conference-discussion', '💬 Thảo Luận Khoa Học', 'Ngôn ngữ hội nghị và giao tiếp chuyên môn.', '[{"id":"med-conf-discussion-001","en":"I agree with your point, however I''d like to add...","vn":"Tôi đồng ý với quan điểm của bạn, nhưng tôi muốn bổ sung...","note":""},{"id":"med-conf-discussion-002","en":"Based on the evidence, I think the first-line treatment should be...","vn":"Dựa trên bằng chứng, tôi nghĩ điều trị hàng đầu nên là...","note":""},{"id":"med-conf-discussion-003","en":"What does the current literature say about this?","vn":"Tài liệu hiện tại nói gì về vấn đề này?","note":"literature = tài liệu y văn"},{"id":"med-conf-discussion-004","en":"That''s a valid point. We''ve seen similar results.","vn":"Đó là điểm hợp lệ. Chúng tôi cũng thấy kết quả tương tự.","note":""},{"id":"med-conf-discussion-005","en":"Could you clarify what you mean by that?","vn":"Bạn có thể làm rõ ý bạn không?","note":"Câu lịch sự để hỏi lại khi chưa hiểu."}]', 102, true),
('medication', 'medication-core', 'Medication Instructions', 'Huong dan thuoc thong dung cho benh nhan.', '[{"id":"med-medi-001","en":"Take this medication 3 times a day — morning, noon, and evening.","vn":"Uống thuốc này 3 lần/ngày — sáng, trưa, tối.","note":"OPC3"},{"id":"med-medi-002","en":"Take one sachet after each main meal and before bedtime — 4 times a day.","vn":"Uống 1 gói sau mỗi 3 bữa ăn chính và trước khi ngủ — 4 lần/ngày.","note":"GEL"},{"id":"med-medi-003","en":"Take paracetamol only when your temperature is above 38.5°C or when you have significant pain. One tablet every 6 hours.","vn":"Uống paracetamol khi sốt từ 38.5°C hoặc đau nhiều. 1 viên cách 6 giờ.","note":"PARA"},{"id":"med-medi-004","en":"Take this stomach tablet once daily, 30 minutes before breakfast.","vn":"Uống thuốc dạ dày 1 viên mỗi ngày, trước bữa sáng 30 phút.","note":"PPI"},{"id":"med-medi-005","en":"Ear drops: 5 drops into the ear twice a day — morning and evening.","vn":"Thuốc nhỏ tai: 5 giọt vào tai, ngày 2 lần — sáng và tối.","note":"NT"},{"id":"med-medi-006","en":"Nasal spray: use every morning, 2 sprays in each nostril.","vn":"Thuốc xịt mũi: dùng mỗi sáng, 2 nhát mỗi bên mũi.","note":"XM"},{"id":"med-medi-007","en":"This tablet dissolves under your tongue — do not swallow it.","vn":"Viên này ngậm dưới lưỡi — không nuốt.","note":"NDL - Ngậm dưới lưỡi"},{"id":"med-medi-008","en":"Finish the entire course of antibiotics even if you feel better.","vn":"Uống hết kháng sinh kể cả khi thấy khỏe hơn.","note":"Quan trọng! Không bỏ thuốc giữa chừng."},{"id":"med-medi-009","en":"Take this with food to protect your stomach.","vn":"Uống thuốc này cùng bữa ăn để bảo vệ dạ dày.","note":""},{"id":"med-medi-010","en":"If you experience any side effects, stop the medication and come back to see me.","vn":"Nếu có tác dụng phụ, ngừng thuốc và quay lại gặp tôi.","note":""},{"id":"med-medi-011","en":"Take 15ml three times a day — morning, noon, and evening.","vn":"Uống 15ml ngày 3 lần — sáng, trưa, tối.","note":"OPC3"},{"id":"med-medi-012","en":"Do not exceed 4 tablets of paracetamol in 24 hours.","vn":"Không dùng quá 4 viên paracetamol trong 24 giờ.","note":""}]', 200, true),
('medical_daily', 'medical-daily-restaurant', '🍜 Nhà Hàng', 'Cum giao tiep nhanh co the dung ngay trong phong kham.', '[{"id":"med-daily-restaurant-001","en":"A table for two, please.","vn":"Cho tôi một bàn cho 2 người.","note":""},{"id":"med-daily-restaurant-002","en":"Could I see the menu, please?","vn":"Cho tôi xem thực đơn được không?","note":""},{"id":"med-daily-restaurant-003","en":"I''d like to order, please.","vn":"Tôi muốn gọi món.","note":""},{"id":"med-daily-restaurant-004","en":"What do you recommend?","vn":"Bạn gợi ý món gì?","note":"Câu hỏi tự nhiên và lịch sự"},{"id":"med-daily-restaurant-005","en":"I''m allergic to shellfish.","vn":"Tôi bị dị ứng hải sản có vỏ.","note":"shellfish = tôm cua ốc"},{"id":"med-daily-restaurant-006","en":"Could I have the bill, please?","vn":"Cho tôi tính tiền được không?","note":""},{"id":"med-daily-restaurant-007","en":"Is service charge included?","vn":"Đã bao gồm phí phục vụ chưa?","note":""},{"id":"med-daily-restaurant-008","en":"This is delicious! Compliments to the chef.","vn":"Ngon lắm! Khen đầu bếp giúp tôi.","note":""}]', 300, true),
('medical_daily', 'medical-daily-airport', '✈️ Sân Bay', 'Cum giao tiep nhanh co the dung ngay trong phong kham.', '[{"id":"med-daily-airport-001","en":"Where is the check-in counter for Vietnam Airlines?","vn":"Quầy check-in của Vietnam Airlines ở đâu?","note":""},{"id":"med-daily-airport-002","en":"I''d like a window seat, please.","vn":"Cho tôi ghế cạnh cửa sổ.","note":"window seat = ghế cửa sổ, aisle seat = ghế lối đi"},{"id":"med-daily-airport-003","en":"Is this flight on time?","vn":"Chuyến bay này có đúng giờ không?","note":""},{"id":"med-daily-airport-004","en":"My flight has been delayed. Can you rebook me?","vn":"Chuyến bay của tôi bị delay. Bạn có thể đặt lại không?","note":""},{"id":"med-daily-airport-005","en":"Where is gate B12?","vn":"Cửa ra máy bay B12 ở đâu?","note":"gate = cửa ra máy bay"},{"id":"med-daily-airport-006","en":"I have a connecting flight. Will I make it in time?","vn":"Tôi có chuyến bay nối. Tôi có kịp không?","note":"connecting flight = chuyến bay nối"},{"id":"med-daily-airport-007","en":"Can I have a transit hotel voucher?","vn":"Tôi có thể nhận voucher khách sạn quá cảnh không?","note":"transit = quá cảnh"}]', 301, true),
('medical_daily', 'medical-daily-hotel', '🏨 Khách Sạn', 'Cum giao tiep nhanh co the dung ngay trong phong kham.', '[{"id":"med-daily-hotel-001","en":"I have a reservation under the name Dr. [Name].","vn":"Tôi có đặt phòng với tên bác sĩ [Tên].","note":""},{"id":"med-daily-hotel-002","en":"Could I have a room with a city view?","vn":"Tôi có thể có phòng nhìn ra thành phố không?","note":""},{"id":"med-daily-hotel-003","en":"What time is checkout?","vn":"Check-out lúc mấy giờ?","note":""},{"id":"med-daily-hotel-004","en":"Is breakfast included?","vn":"Có bao gồm bữa sáng không?","note":""},{"id":"med-daily-hotel-005","en":"The air conditioning in my room isn''t working.","vn":"Điều hòa trong phòng tôi không hoạt động.","note":""},{"id":"med-daily-hotel-006","en":"Could you send someone to fix it?","vn":"Bạn có thể cử ai đến sửa không?","note":""},{"id":"med-daily-hotel-007","en":"Can I extend my stay by one night?","vn":"Tôi có thể ở thêm một đêm nữa không?","note":""}]', 302, true),
('medical_daily', 'medical-daily-smalltalk', '💬 Small Talk', 'Cum giao tiep nhanh co the dung ngay trong phong kham.', '[{"id":"med-daily-smalltalk-001","en":"Nice to meet you! I''m a doctor from Vietnam.","vn":"Rất vui được gặp bạn! Tôi là bác sĩ từ Việt Nam.","note":""},{"id":"med-daily-smalltalk-002","en":"I specialize in ENT — ear, nose, and throat.","vn":"Tôi chuyên khoa Tai Mũi Họng.","note":"ENT = Ear, Nose, Throat"},{"id":"med-daily-smalltalk-003","en":"How long have you been in this field?","vn":"Bạn đã làm trong lĩnh vực này bao lâu rồi?","note":""},{"id":"med-daily-smalltalk-004","en":"The weather here is quite different from Vietnam!","vn":"Thời tiết ở đây khá khác Việt Nam nhỉ!","note":""},{"id":"med-daily-smalltalk-005","en":"Could you say that again, please? I want to make sure I understand.","vn":"Bạn có thể nói lại không? Tôi muốn chắc chắn mình hiểu đúng.","note":"Câu quan trọng khi không nghe rõ!"},{"id":"med-daily-smalltalk-006","en":"I''m sorry, could you speak a little more slowly?","vn":"Xin lỗi, bạn có thể nói chậm hơn một chút không?","note":"Đừng ngại dùng câu này!"},{"id":"med-daily-smalltalk-007","en":"Thank you so much. It''s been a pleasure talking with you.","vn":"Cảm ơn bạn rất nhiều. Rất vui được nói chuyện với bạn.","note":""}]', 303, true),
('medical_daily', 'medical-daily-shopping', '🛍️ Mua Sắm', 'Cum giao tiep nhanh co the dung ngay trong phong kham.', '[{"id":"med-daily-shopping-001","en":"How much is this?","vn":"Cái này bao nhiêu tiền?","note":""},{"id":"med-daily-shopping-002","en":"Do you have this in a different size?","vn":"Bạn có cái này size khác không?","note":""},{"id":"med-daily-shopping-003","en":"Can I try this on?","vn":"Tôi có thể mặc thử không?","note":""},{"id":"med-daily-shopping-004","en":"I''ll take it.","vn":"Tôi lấy cái này.","note":""},{"id":"med-daily-shopping-005","en":"Do you accept credit cards?","vn":"Bạn có nhận thẻ tín dụng không?","note":""},{"id":"med-daily-shopping-006","en":"Could I get a receipt, please?","vn":"Cho tôi hóa đơn được không?","note":""},{"id":"med-daily-shopping-007","en":"Is this tax-free for tourists?","vn":"Cái này có miễn thuế cho khách du lịch không?","note":""}]', 304, true);
insert into procedures (slug, title, vn_title, icon, steps, sort_order, published) values
('earwax', 'Earwax Removal', 'Lấy ráy tai', '👂', '[{"id":"med-proc-001-step-1","en":"I need to remove some earwax from your ear today.","vn":"Hôm nay tôi cần lấy ráy tai cho bạn."},{"id":"med-proc-001-step-2","en":"Please lie on your side — the right ear facing up.","vn":"Vui lòng nằm nghiêng, tai phải hướng lên trên."},{"id":"med-proc-001-step-3","en":"First, I''ll soften the earwax with a few drops of glycerine. This will take about 10 minutes.","vn":"Đầu tiên tôi sẽ nhỏ glycerine để làm mềm ráy tai, khoảng 10 phút."},{"id":"med-proc-001-step-4","en":"I''m going to use a suction device to remove the earwax. You may hear a suction sound — that''s normal.","vn":"Tôi sẽ dùng máy hút để lấy ráy tai. Bạn sẽ nghe tiếng hút — bình thường."},{"id":"med-proc-001-step-5","en":"Please hold very still. Try not to move your head.","vn":"Vui lòng giữ thật yên. Đừng cử động đầu."},{"id":"med-proc-001-step-6","en":"You may feel some mild discomfort but it should not be painful. Tell me if it hurts.","vn":"Bạn có thể hơi khó chịu nhưng không nên đau. Cho tôi biết nếu đau."},{"id":"med-proc-001-step-7","en":"I''ve finished. The earwax has been removed successfully.","vn":"Xong rồi. Đã lấy ráy tai thành công."},{"id":"med-proc-001-step-8","en":"Please avoid getting water in your ear for the next 24 hours.","vn":"Tránh để nước vào tai trong 24 giờ tới."}]', 0, true),
('ear-wash', 'Ear Canal Irrigation', 'Rửa ống tai ngoài', '💧', '[{"id":"med-proc-002-step-1","en":"I''m going to clean your ear canal today.","vn":"Tôi sẽ rửa sạch ống tai của bạn hôm nay."},{"id":"med-proc-002-step-2","en":"Please lie on your side, with the affected ear facing up.","vn":"Vui lòng nằm nghiêng, tai cần rửa hướng lên."},{"id":"med-proc-002-step-3","en":"I''ll flush your ear with a diluted hydrogen peroxide solution. It may bubble — that''s normal.","vn":"Tôi sẽ bơm dung dịch oxy già pha loãng. Có thể có bọt — bình thường."},{"id":"med-proc-002-step-4","en":"Then I''ll use a suction device to remove the fluid and discharge.","vn":"Sau đó tôi dùng máy hút để hút dịch và mủ ra."},{"id":"med-proc-002-step-5","en":"I''ll clean the outer ear canal with povidone-iodine solution.","vn":"Tôi sẽ vệ sinh ống tai ngoài bằng dung dịch povidine pha loãng."},{"id":"med-proc-002-step-6","en":"How are you feeling? Any pain or discomfort?","vn":"Bạn thấy thế nào? Có đau hay khó chịu không?"},{"id":"med-proc-002-step-7","en":"The procedure is complete. Your ear is clean now.","vn":"Thủ thuật xong rồi. Tai bạn đã sạch."}]', 1, true),
('nasal-wash', 'Nasal Sinus Irrigation', 'Rửa mũi xoang (HRM)', '🌊', '[{"id":"med-proc-003-step-1","en":"I''m going to wash out your nasal sinuses today.","vn":"Hôm nay tôi sẽ rửa mũi xoang cho bạn."},{"id":"med-proc-003-step-2","en":"Please lean your head back as far as comfortable.","vn":"Hãy ngửa đầu ra sau hết mức bạn thoải mái."},{"id":"med-proc-003-step-3","en":"First I''ll apply a decongestant spray to open up your nasal passages.","vn":"Đầu tiên tôi sẽ xịt thuốc co mạch để thông mũi."},{"id":"med-proc-003-step-4","en":"I''ll now block one nostril and ask you to say ''kê kê kê'' to close your soft palate.","vn":"Tôi bịt một bên mũi và nhờ bạn nói ''kê kê kê'' để đóng buồm hàm."},{"id":"med-proc-003-step-5","en":"I''ll flush the saline solution in and then suction it out with the secretions.","vn":"Tôi sẽ bơm nước muối vào và hút ra cùng dịch tiết."},{"id":"med-proc-003-step-6","en":"After the irrigation, I''ll put the medication into your sinuses.","vn":"Sau khi rửa, tôi sẽ đặt thuốc vào xoang cho bạn."},{"id":"med-proc-003-step-7","en":"Please remain lying down for a few minutes so the medication doesn''t drain into your throat.","vn":"Vui lòng nằm vài phút để thuốc không chảy xuống họng."}]', 2, true),
('ear-drops', 'Ear Drop Administration', 'Nhỏ tai (NT)', '💊', '[{"id":"med-proc-004-step-1","en":"I''m going to put some ear drops in your ear.","vn":"Tôi sẽ nhỏ thuốc vào tai bạn."},{"id":"med-proc-004-step-2","en":"Please tilt your head so the affected ear faces upward.","vn":"Vui lòng nghiêng đầu để tai cần nhỏ thuốc hướng lên."},{"id":"med-proc-004-step-3","en":"I''ll put 5 drops into the ear. You''ll feel the drops go in — stay still for a moment.","vn":"Tôi sẽ nhỏ 5 giọt vào tai. Bạn sẽ cảm thấy giọt thuốc — giữ yên một lúc."},{"id":"med-proc-004-step-4","en":"At home, use the ear drops twice a day — morning and evening. 5 drops each time.","vn":"Ở nhà dùng thuốc nhỏ tai 2 lần/ngày — sáng và tối. Mỗi lần 5 giọt."},{"id":"med-proc-004-step-5","en":"After putting the drops in, press gently on the small bump in front of your ear to help the drops go in.","vn":"Sau khi nhỏ thuốc, ấn nhẹ vào nắp tai phía trước để thuốc vào sâu hơn."}]', 3, true),
('nasal-spray', 'Nasal Spray Instruction', 'Xịt mũi (XM)', '💨', '[{"id":"med-proc-005-step-1","en":"I''m prescribing a nasal spray for you.","vn":"Tôi kê thuốc xịt mũi cho bạn."},{"id":"med-proc-005-step-2","en":"Use it once every morning — 2 sprays in each nostril.","vn":"Dùng mỗi buổi sáng — 2 nhát mỗi bên mũi."},{"id":"med-proc-005-step-3","en":"Before using, blow your nose gently to clear it.","vn":"Trước khi xịt, hỉ mũi nhẹ nhàng để thông mũi."},{"id":"med-proc-005-step-4","en":"Point the nozzle slightly outward — away from the center of your nose.","vn":"Hướng đầu xịt hơi ra ngoài — không nhắm vào vách ngăn mũi."},{"id":"med-proc-005-step-5","en":"Breathe in gently through your nose as you spray.","vn":"Hít nhẹ qua mũi trong khi xịt."},{"id":"med-proc-005-step-6","en":"Don''t blow your nose immediately after — wait at least 5 minutes.","vn":"Không hỉ mũi ngay sau khi xịt — đợi ít nhất 5 phút."}]', 4, true),
('endoscopy', 'Nasal Endoscopy', 'Nội soi mũi', '🔭', '[{"id":"med-proc-006-step-1","en":"I need to perform a nasal endoscopy to examine the inside of your nose.","vn":"Tôi cần nội soi mũi để xem bên trong mũi bạn."},{"id":"med-proc-006-step-2","en":"I''ll insert a thin, flexible tube with a small camera into your nose.","vn":"Tôi sẽ đưa ống nhỏ có camera vào mũi bạn."},{"id":"med-proc-006-step-3","en":"First, I''ll apply some local anesthetic to reduce discomfort.","vn":"Đầu tiên tôi sẽ xịt thuốc tê tại chỗ để giảm khó chịu."},{"id":"med-proc-006-step-4","en":"You''ll feel some pressure but it should not be painful. Please breathe through your mouth.","vn":"Bạn sẽ cảm thấy áp lực nhưng không nên đau. Hãy thở bằng miệng."},{"id":"med-proc-006-step-5","en":"I can see some polyps / inflammation / mucus in your nasal passage.","vn":"Tôi thấy có polyp / viêm / dịch nhầy trong đường mũi bạn."},{"id":"med-proc-006-step-6","en":"The examination is complete. Please don''t blow your nose forcefully for the next hour.","vn":"Khám xong rồi. Vui lòng không hỉ mũi mạnh trong vòng 1 giờ."}]', 5, true),
('foreign-body-ear', 'Foreign Body — Ear', 'Lấy dị vật tai', '🔎', '[{"id":"med-proc-007-step-1","en":"I can see there''s a foreign object in your ear. I''ll remove it for you.","vn":"Tôi thấy có dị vật trong tai bạn. Tôi sẽ lấy ra cho bạn."},{"id":"med-proc-007-step-2","en":"Please remain very still during this procedure. It''s important you don''t move.","vn":"Vui lòng giữ thật yên trong khi làm thủ thuật. Quan trọng là không cử động."},{"id":"med-proc-007-step-3","en":"I''ll use a specialized instrument to gently remove the object.","vn":"Tôi sẽ dùng dụng cụ chuyên biệt để lấy dị vật ra nhẹ nhàng."},{"id":"med-proc-007-step-4","en":"This may feel a little uncomfortable but I''ll be as gentle as possible.","vn":"Có thể hơi khó chịu nhưng tôi sẽ cố gắng nhẹ nhàng nhất có thể."},{"id":"med-proc-007-step-5","en":"The object has been removed. Your ear looks clear now.","vn":"Đã lấy dị vật ra rồi. Tai bạn trông ổn rồi."},{"id":"med-proc-007-step-6","en":"Make sure nothing is placed in the ear again.","vn":"Đảm bảo không đặt gì vào tai nữa."}]', 6, true),
('foreign-body-nose', 'Foreign Body — Nose', 'Lấy dị vật mũi', '👃', '[{"id":"med-proc-008-step-1","en":"Your child has a foreign object stuck in their nose. I''ll remove it now.","vn":"Con bạn có dị vật trong mũi. Tôi sẽ lấy ra ngay bây giờ."},{"id":"med-proc-008-step-2","en":"Please keep your child as calm and still as possible.","vn":"Vui lòng giữ cho trẻ bình tĩnh và yên tĩnh nhất có thể."},{"id":"med-proc-008-step-3","en":"I''ll use a small instrument to carefully retrieve the object.","vn":"Tôi sẽ dùng dụng cụ nhỏ để cẩn thận lấy dị vật ra."},{"id":"med-proc-008-step-4","en":"Try not to try to remove it yourself — it can push the object further in.","vn":"Đừng tự lấy — có thể đẩy dị vật vào sâu hơn."},{"id":"med-proc-008-step-5","en":"Done! The object is out. Please watch that this doesn''t happen again.","vn":"Xong rồi! Đã lấy được. Vui lòng chú ý để không xảy ra lần nữa."}]', 7, true),
('nebulization', 'Nebulization (KDH/KDM)', 'Xông khí dung họng/mũi', '💨', '[{"id":"med-proc-009-step-1","en":"I''m going to give you a nebulizer treatment for your throat and nose.","vn":"Tôi sẽ cho bạn xông khí dung họng và mũi."},{"id":"med-proc-009-step-2","en":"Please sit in a relaxed, comfortable position.","vn":"Vui lòng ngồi thư giãn, thoải mái."},{"id":"med-proc-009-step-3","en":"This mask will deliver the medicated mist — breathe normally through it.","vn":"Mặt nạ này sẽ đưa thuốc dạng sương — thở bình thường qua đó."},{"id":"med-proc-009-step-4","en":"The treatment takes about 10–15 minutes. Just relax.","vn":"Điều trị mất khoảng 10–15 phút. Cứ thư giãn."},{"id":"med-proc-009-step-5","en":"The medication contains an anti-inflammatory and an antibiotic.","vn":"Thuốc có chứa kháng viêm và kháng sinh."},{"id":"med-proc-009-step-6","en":"Try to breathe in deeply and slowly through your nose.","vn":"Cố hít thở sâu và chậm qua mũi."}]', 8, true);
insert into drill_items (legacy_id, category, english, vietnamese, note, sort_order, published) values
('med-consult-greeting-001', 'medical', 'Good morning! Please come in and have a seat.', 'Chào buổi sáng! Mời vào và ngồi đây.', '', 0, true),
('med-consult-greeting-002', 'medical', 'Hello, I''m Dr. [Your name]. How can I help you today?', 'Xin chào, tôi là bác sĩ [Tên]. Hôm nay bạn cần khám gì?', '', 1, true),
('med-consult-greeting-003', 'medical', 'What brings you here today?', 'Hôm nay bạn đến vì vấn đề gì?', 'Câu hỏi mở, thường dùng nhất khi bắt đầu khám.', 2, true),
('med-consult-greeting-004', 'medical', 'How long have you had this problem?', 'Vấn đề này đã được bao lâu rồi?', '', 3, true),
('med-consult-greeting-005', 'medical', 'Is this the first time you''ve experienced this?', 'Đây có phải lần đầu bạn bị như vậy không?', '', 4, true),
('med-consult-greeting-006', 'medical', 'Please describe your symptoms.', 'Hãy mô tả các triệu chứng của bạn.', '', 5, true),
('med-consult-ear-001', 'medical', 'Do you have any ear pain?', 'Bạn có đau tai không?', '', 6, true),
('med-consult-ear-002', 'medical', 'Are you experiencing any hearing loss?', 'Bạn có bị giảm thính lực không?', '', 7, true),
('med-consult-ear-003', 'medical', 'Do you have any ringing in your ears?', 'Bạn có bị ù tai không?', 'Ringing in ears = tinnitus /ˈtɪnɪtəs/', 8, true),
('med-consult-ear-004', 'medical', 'Is there any discharge coming from your ear?', 'Có dịch chảy ra từ tai không?', 'discharge = dịch tiết', 9, true),
('med-consult-ear-005', 'medical', 'Do you feel dizzy or have problems with balance?', 'Bạn có chóng mặt hoặc mất thăng bằng không?', 'dizzy = chóng mặt, balance = thăng bằng', 10, true),
('med-consult-ear-006', 'medical', 'I''m going to examine your ear now. Please hold still.', 'Tôi sẽ khám tai cho bạn bây giờ. Vui lòng giữ yên.', '', 11, true),
('med-consult-ear-007', 'medical', 'I can see some earwax buildup. That''s likely causing the problem.', 'Tôi thấy có ráy tai tích tụ. Đó có thể là nguyên nhân.', 'earwax buildup = ráy tai tích tụ', 12, true),
('med-consult-ear-008', 'medical', 'Your eardrum looks normal.', 'Màng nhĩ của bạn trông bình thường.', 'eardrum = màng nhĩ', 13, true),
('med-consult-ear-009', 'medical', 'There appears to be a foreign object in your ear.', 'Có vẻ có dị vật trong tai bạn.', 'foreign object = dị vật', 14, true),
('med-consult-nose-001', 'medical', 'Do you have a stuffy or blocked nose?', 'Bạn có nghẹt mũi không?', 'stuffy/blocked nose = nghẹt mũi', 15, true),
('med-consult-nose-002', 'medical', 'Are you experiencing any nasal discharge? What color is it?', 'Bạn có chảy nước mũi không? Màu gì?', 'nasal discharge = nước mũi chảy', 16, true),
('med-consult-nose-003', 'medical', 'Do you have frequent nosebleeds?', 'Bạn có hay bị chảy máu mũi không?', 'nosebleed = chảy máu cam', 17, true),
('med-consult-nose-004', 'medical', 'Have you lost your sense of smell?', 'Bạn có mất mùi không?', 'sense of smell = khứu giác', 18, true),
('med-consult-nose-005', 'medical', 'Do you have any allergies?', 'Bạn có bị dị ứng gì không?', '', 19, true),
('med-consult-nose-006', 'medical', 'Has your nose been injured before?', 'Mũi bạn đã từng bị chấn thương chưa?', '', 20, true),
('med-consult-nose-007', 'medical', 'I''m going to spray some decongestant into your nose before the examination.', 'Tôi sẽ xịt thuốc co mạch vào mũi trước khi khám.', 'decongestant = thuốc co mạch/thông mũi', 21, true),
('med-consult-throat-001', 'medical', 'Do you have a sore throat?', 'Bạn có đau họng không?', '', 22, true),
('med-consult-throat-002', 'medical', 'How long have you had trouble swallowing?', 'Bạn bị khó nuốt được bao lâu rồi?', 'swallowing = nuốt', 23, true),
('med-consult-throat-003', 'medical', 'Do you have a hoarse voice?', 'Bạn có bị khàn tiếng không?', 'hoarse = khàn giọng', 24, true),
('med-consult-throat-004', 'medical', 'Please open your mouth and say ''Ahh''.', 'Mở miệng ra và nói ''Ahh''.', 'Câu dùng khi khám họng', 25, true),
('med-consult-throat-005', 'medical', 'Your tonsils are swollen.', 'Amidan của bạn đang sưng.', 'tonsils = amidan', 26, true),
('med-consult-throat-006', 'medical', 'I can see some redness and swelling in your throat.', 'Tôi thấy có vùng đỏ và sưng trong họng bạn.', '', 27, true),
('med-consult-diagnosis-001', 'medical', 'Based on my examination, you have a middle ear infection.', 'Dựa trên khám bệnh, bạn bị viêm tai giữa.', 'middle ear infection = viêm tai giữa', 28, true),
('med-consult-diagnosis-002', 'medical', 'You have sinusitis — inflammation of the sinuses.', 'Bạn bị viêm xoang.', 'sinusitis = viêm xoang', 29, true),
('med-consult-diagnosis-003', 'medical', 'I''d like to do a nasal endoscopy to get a better look.', 'Tôi muốn làm nội soi mũi để xem rõ hơn.', 'endoscopy = nội soi', 30, true),
('med-consult-diagnosis-004', 'medical', 'I''m going to prescribe some antibiotics for you.', 'Tôi sẽ kê kháng sinh cho bạn.', 'prescribe = kê toa, antibiotics = kháng sinh', 31, true),
('med-consult-diagnosis-005', 'medical', 'Please come back in one week if it doesn''t improve.', 'Nếu không cải thiện, vui lòng tái khám sau một tuần.', '', 32, true),
('med-consult-diagnosis-006', 'medical', 'Do you have any questions for me?', 'Bạn có câu hỏi gì cho tôi không?', 'Luôn hỏi câu này trước khi kết thúc khám.', 33, true),
('med-consult-diagnosis-007', 'medical', 'I''ll refer you to a specialist.', 'Tôi sẽ giới thiệu bạn đến bác sĩ chuyên khoa.', 'refer = giới thiệu, specialist = bác sĩ chuyên khoa', 34, true),
('drill-proc-0', 'medical', 'I need to remove some earwax from your ear today.', 'Hôm nay tôi cần lấy ráy tai cho bạn.', '', 35, true),
('drill-proc-1', 'medical', 'Please lie on your side — the right ear facing up.', 'Vui lòng nằm nghiêng, tai phải hướng lên trên.', '', 36, true),
('drill-proc-2', 'medical', 'First, I''ll soften the earwax with a few drops of glycerine. This will take about 10 minutes.', 'Đầu tiên tôi sẽ nhỏ glycerine để làm mềm ráy tai, khoảng 10 phút.', '', 37, true),
('drill-proc-3', 'medical', 'I''m going to use a suction device to remove the earwax. You may hear a suction sound — that''s normal.', 'Tôi sẽ dùng máy hút để lấy ráy tai. Bạn sẽ nghe tiếng hút — bình thường.', '', 38, true),
('drill-proc-4', 'medical', 'Please hold very still. Try not to move your head.', 'Vui lòng giữ thật yên. Đừng cử động đầu.', '', 39, true),
('drill-proc-5', 'medical', 'You may feel some mild discomfort but it should not be painful. Tell me if it hurts.', 'Bạn có thể hơi khó chịu nhưng không nên đau. Cho tôi biết nếu đau.', '', 40, true),
('drill-proc-6', 'medical', 'I''ve finished. The earwax has been removed successfully.', 'Xong rồi. Đã lấy ráy tai thành công.', '', 41, true),
('drill-proc-7', 'medical', 'Please avoid getting water in your ear for the next 24 hours.', 'Tránh để nước vào tai trong 24 giờ tới.', '', 42, true),
('drill-proc-8', 'medical', 'I''m going to clean your ear canal today.', 'Tôi sẽ rửa sạch ống tai của bạn hôm nay.', '', 43, true),
('drill-proc-9', 'medical', 'Please lie on your side, with the affected ear facing up.', 'Vui lòng nằm nghiêng, tai cần rửa hướng lên.', '', 44, true),
('drill-proc-10', 'medical', 'I''ll flush your ear with a diluted hydrogen peroxide solution. It may bubble — that''s normal.', 'Tôi sẽ bơm dung dịch oxy già pha loãng. Có thể có bọt — bình thường.', '', 45, true),
('drill-proc-11', 'medical', 'Then I''ll use a suction device to remove the fluid and discharge.', 'Sau đó tôi dùng máy hút để hút dịch và mủ ra.', '', 46, true),
('drill-proc-12', 'medical', 'I''ll clean the outer ear canal with povidone-iodine solution.', 'Tôi sẽ vệ sinh ống tai ngoài bằng dung dịch povidine pha loãng.', '', 47, true),
('drill-proc-13', 'medical', 'How are you feeling? Any pain or discomfort?', 'Bạn thấy thế nào? Có đau hay khó chịu không?', '', 48, true),
('drill-proc-14', 'medical', 'The procedure is complete. Your ear is clean now.', 'Thủ thuật xong rồi. Tai bạn đã sạch.', '', 49, true),
('drill-proc-15', 'medical', 'I''m going to wash out your nasal sinuses today.', 'Hôm nay tôi sẽ rửa mũi xoang cho bạn.', '', 50, true),
('drill-proc-16', 'medical', 'Please lean your head back as far as comfortable.', 'Hãy ngửa đầu ra sau hết mức bạn thoải mái.', '', 51, true),
('drill-proc-17', 'medical', 'First I''ll apply a decongestant spray to open up your nasal passages.', 'Đầu tiên tôi sẽ xịt thuốc co mạch để thông mũi.', '', 52, true),
('drill-proc-18', 'medical', 'I''ll now block one nostril and ask you to say ''kê kê kê'' to close your soft palate.', 'Tôi bịt một bên mũi và nhờ bạn nói ''kê kê kê'' để đóng buồm hàm.', '', 53, true),
('drill-proc-19', 'medical', 'I''ll flush the saline solution in and then suction it out with the secretions.', 'Tôi sẽ bơm nước muối vào và hút ra cùng dịch tiết.', '', 54, true),
('drill-proc-20', 'medical', 'After the irrigation, I''ll put the medication into your sinuses.', 'Sau khi rửa, tôi sẽ đặt thuốc vào xoang cho bạn.', '', 55, true),
('drill-proc-21', 'medical', 'Please remain lying down for a few minutes so the medication doesn''t drain into your throat.', 'Vui lòng nằm vài phút để thuốc không chảy xuống họng.', '', 56, true),
('drill-proc-22', 'medical', 'I''m going to put some ear drops in your ear.', 'Tôi sẽ nhỏ thuốc vào tai bạn.', '', 57, true),
('drill-proc-23', 'medical', 'Please tilt your head so the affected ear faces upward.', 'Vui lòng nghiêng đầu để tai cần nhỏ thuốc hướng lên.', '', 58, true),
('drill-proc-24', 'medical', 'I''ll put 5 drops into the ear. You''ll feel the drops go in — stay still for a moment.', 'Tôi sẽ nhỏ 5 giọt vào tai. Bạn sẽ cảm thấy giọt thuốc — giữ yên một lúc.', '', 59, true),
('drill-proc-25', 'medical', 'At home, use the ear drops twice a day — morning and evening. 5 drops each time.', 'Ở nhà dùng thuốc nhỏ tai 2 lần/ngày — sáng và tối. Mỗi lần 5 giọt.', '', 60, true),
('drill-proc-26', 'medical', 'After putting the drops in, press gently on the small bump in front of your ear to help the drops go in.', 'Sau khi nhỏ thuốc, ấn nhẹ vào nắp tai phía trước để thuốc vào sâu hơn.', '', 61, true),
('drill-proc-27', 'medical', 'I''m prescribing a nasal spray for you.', 'Tôi kê thuốc xịt mũi cho bạn.', '', 62, true),
('drill-proc-28', 'medical', 'Use it once every morning — 2 sprays in each nostril.', 'Dùng mỗi buổi sáng — 2 nhát mỗi bên mũi.', '', 63, true),
('drill-proc-29', 'medical', 'Before using, blow your nose gently to clear it.', 'Trước khi xịt, hỉ mũi nhẹ nhàng để thông mũi.', '', 64, true),
('drill-proc-30', 'medical', 'Point the nozzle slightly outward — away from the center of your nose.', 'Hướng đầu xịt hơi ra ngoài — không nhắm vào vách ngăn mũi.', '', 65, true),
('drill-proc-31', 'medical', 'Breathe in gently through your nose as you spray.', 'Hít nhẹ qua mũi trong khi xịt.', '', 66, true),
('drill-proc-32', 'medical', 'Don''t blow your nose immediately after — wait at least 5 minutes.', 'Không hỉ mũi ngay sau khi xịt — đợi ít nhất 5 phút.', '', 67, true),
('drill-proc-33', 'medical', 'I need to perform a nasal endoscopy to examine the inside of your nose.', 'Tôi cần nội soi mũi để xem bên trong mũi bạn.', '', 68, true),
('drill-proc-34', 'medical', 'I''ll insert a thin, flexible tube with a small camera into your nose.', 'Tôi sẽ đưa ống nhỏ có camera vào mũi bạn.', '', 69, true),
('drill-proc-35', 'medical', 'First, I''ll apply some local anesthetic to reduce discomfort.', 'Đầu tiên tôi sẽ xịt thuốc tê tại chỗ để giảm khó chịu.', '', 70, true),
('drill-proc-36', 'medical', 'You''ll feel some pressure but it should not be painful. Please breathe through your mouth.', 'Bạn sẽ cảm thấy áp lực nhưng không nên đau. Hãy thở bằng miệng.', '', 71, true),
('drill-proc-37', 'medical', 'I can see some polyps / inflammation / mucus in your nasal passage.', 'Tôi thấy có polyp / viêm / dịch nhầy trong đường mũi bạn.', '', 72, true),
('drill-proc-38', 'medical', 'The examination is complete. Please don''t blow your nose forcefully for the next hour.', 'Khám xong rồi. Vui lòng không hỉ mũi mạnh trong vòng 1 giờ.', '', 73, true),
('drill-proc-39', 'medical', 'I can see there''s a foreign object in your ear. I''ll remove it for you.', 'Tôi thấy có dị vật trong tai bạn. Tôi sẽ lấy ra cho bạn.', '', 74, true),
('drill-proc-40', 'medical', 'Please remain very still during this procedure. It''s important you don''t move.', 'Vui lòng giữ thật yên trong khi làm thủ thuật. Quan trọng là không cử động.', '', 75, true),
('drill-proc-41', 'medical', 'I''ll use a specialized instrument to gently remove the object.', 'Tôi sẽ dùng dụng cụ chuyên biệt để lấy dị vật ra nhẹ nhàng.', '', 76, true),
('drill-proc-42', 'medical', 'This may feel a little uncomfortable but I''ll be as gentle as possible.', 'Có thể hơi khó chịu nhưng tôi sẽ cố gắng nhẹ nhàng nhất có thể.', '', 77, true),
('drill-proc-43', 'medical', 'The object has been removed. Your ear looks clear now.', 'Đã lấy dị vật ra rồi. Tai bạn trông ổn rồi.', '', 78, true),
('drill-proc-44', 'medical', 'Make sure nothing is placed in the ear again.', 'Đảm bảo không đặt gì vào tai nữa.', '', 79, true),
('drill-proc-45', 'medical', 'Your child has a foreign object stuck in their nose. I''ll remove it now.', 'Con bạn có dị vật trong mũi. Tôi sẽ lấy ra ngay bây giờ.', '', 80, true),
('drill-proc-46', 'medical', 'Please keep your child as calm and still as possible.', 'Vui lòng giữ cho trẻ bình tĩnh và yên tĩnh nhất có thể.', '', 81, true),
('drill-proc-47', 'medical', 'I''ll use a small instrument to carefully retrieve the object.', 'Tôi sẽ dùng dụng cụ nhỏ để cẩn thận lấy dị vật ra.', '', 82, true),
('drill-proc-48', 'medical', 'Try not to try to remove it yourself — it can push the object further in.', 'Đừng tự lấy — có thể đẩy dị vật vào sâu hơn.', '', 83, true),
('drill-proc-49', 'medical', 'Done! The object is out. Please watch that this doesn''t happen again.', 'Xong rồi! Đã lấy được. Vui lòng chú ý để không xảy ra lần nữa.', '', 84, true),
('drill-proc-50', 'medical', 'I''m going to give you a nebulizer treatment for your throat and nose.', 'Tôi sẽ cho bạn xông khí dung họng và mũi.', '', 85, true),
('drill-proc-51', 'medical', 'Please sit in a relaxed, comfortable position.', 'Vui lòng ngồi thư giãn, thoải mái.', '', 86, true),
('drill-proc-52', 'medical', 'This mask will deliver the medicated mist — breathe normally through it.', 'Mặt nạ này sẽ đưa thuốc dạng sương — thở bình thường qua đó.', '', 87, true),
('drill-proc-53', 'medical', 'The treatment takes about 10–15 minutes. Just relax.', 'Điều trị mất khoảng 10–15 phút. Cứ thư giãn.', '', 88, true),
('drill-proc-54', 'medical', 'The medication contains an anti-inflammatory and an antibiotic.', 'Thuốc có chứa kháng viêm và kháng sinh.', '', 89, true),
('drill-proc-55', 'medical', 'Try to breathe in deeply and slowly through your nose.', 'Cố hít thở sâu và chậm qua mũi.', '', 90, true),
('drill-medi-0', 'medical', 'Take this medication 3 times a day — morning, noon, and evening.', 'Uống thuốc này 3 lần/ngày — sáng, trưa, tối.', 'OPC3', 91, true),
('drill-medi-1', 'medical', 'Take one sachet after each main meal and before bedtime — 4 times a day.', 'Uống 1 gói sau mỗi 3 bữa ăn chính và trước khi ngủ — 4 lần/ngày.', 'GEL', 92, true),
('drill-medi-2', 'medical', 'Take paracetamol only when your temperature is above 38.5°C or when you have significant pain. One tablet every 6 hours.', 'Uống paracetamol khi sốt từ 38.5°C hoặc đau nhiều. 1 viên cách 6 giờ.', 'PARA', 93, true),
('drill-medi-3', 'medical', 'Take this stomach tablet once daily, 30 minutes before breakfast.', 'Uống thuốc dạ dày 1 viên mỗi ngày, trước bữa sáng 30 phút.', 'PPI', 94, true),
('drill-medi-4', 'medical', 'Ear drops: 5 drops into the ear twice a day — morning and evening.', 'Thuốc nhỏ tai: 5 giọt vào tai, ngày 2 lần — sáng và tối.', 'NT', 95, true),
('drill-medi-5', 'medical', 'Nasal spray: use every morning, 2 sprays in each nostril.', 'Thuốc xịt mũi: dùng mỗi sáng, 2 nhát mỗi bên mũi.', 'XM', 96, true),
('drill-medi-6', 'medical', 'This tablet dissolves under your tongue — do not swallow it.', 'Viên này ngậm dưới lưỡi — không nuốt.', 'NDL - Ngậm dưới lưỡi', 97, true),
('drill-medi-7', 'medical', 'Finish the entire course of antibiotics even if you feel better.', 'Uống hết kháng sinh kể cả khi thấy khỏe hơn.', 'Quan trọng! Không bỏ thuốc giữa chừng.', 98, true),
('drill-medi-8', 'medical', 'Take this with food to protect your stomach.', 'Uống thuốc này cùng bữa ăn để bảo vệ dạ dày.', '', 99, true),
('drill-medi-9', 'medical', 'If you experience any side effects, stop the medication and come back to see me.', 'Nếu có tác dụng phụ, ngừng thuốc và quay lại gặp tôi.', '', 100, true),
('drill-medi-10', 'medical', 'Take 15ml three times a day — morning, noon, and evening.', 'Uống 15ml ngày 3 lần — sáng, trưa, tối.', 'OPC3', 101, true),
('drill-medi-11', 'medical', 'Do not exceed 4 tablets of paracetamol in 24 hours.', 'Không dùng quá 4 viên paracetamol trong 24 giờ.', '', 102, true),
('daily-greetings-001', 'daily-life', 'Good morning! How are you doing today?', 'Chào buổi sáng! Hôm nay bạn thế nào?', 'Câu mở đầu lịch sự nhất', 103, true),
('daily-greetings-002', 'daily-life', 'I''m doing great, thanks for asking!', 'Tôi rất tốt, cảm ơn bạn đã hỏi!', '', 104, true),
('daily-greetings-003', 'daily-life', 'Not bad, could be better. How about you?', 'Cũng ổn thôi, có thể tốt hơn. Còn bạn thì sao?', 'Câu trung thực nhưng lịch sự', 105, true),
('daily-greetings-004', 'daily-life', 'Long time no see! What have you been up to?', 'Lâu không gặp! Dạo này bạn làm gì vậy?', '', 106, true),
('daily-greetings-005', 'daily-life', 'It''s been a while. You look great!', 'Lâu rồi không gặp. Bạn trông rất tốt!', '', 107, true),
('daily-greetings-006', 'daily-life', 'What a small world — fancy meeting you here!', 'Thế giới thật nhỏ — thật trùng hợp khi gặp bạn ở đây!', 'Khi gặp người quen bất ngờ', 108, true),
('daily-greetings-007', 'daily-life', 'I''m sorry, I didn''t catch your name?', 'Xin lỗi, tôi chưa kịp nghe tên bạn?', 'Lịch sự khi không nghe rõ tên', 109, true),
('daily-greetings-008', 'daily-life', 'It''s nice to meet you. I''m [name].', 'Rất vui được gặp bạn. Tôi là [tên].', '', 110, true),
('daily-greetings-009', 'daily-life', 'How''s the family?', 'Gia đình bạn thế nào rồi?', '', 111, true),
('daily-greetings-010', 'daily-life', 'I''ve been keeping busy. Work has been hectic lately.', 'Tôi khá bận. Công việc dạo này hơi hối hả.', 'hectic = bận rộn, hối hả', 112, true),
('daily-greetings-011', 'daily-life', 'Anyway, it was great running into you!', 'Dù sao, thật vui khi tình cờ gặp bạn!', 'Câu khi chia tay', 113, true),
('daily-greetings-012', 'daily-life', 'Take care! See you around.', 'Bảo trọng nhé! Hẹn gặp lại.', '', 114, true),
('daily-cafe-001', 'daily-life', 'Hi, can I get a medium latte, please?', 'Xin chào, cho tôi một ly latte cỡ vừa nhé?', 'medium = cỡ vừa (Starbucks: tall/grande/venti)', 115, true),
('daily-cafe-002', 'daily-life', 'Could I have that with oat milk instead?', 'Bạn có thể dùng sữa yến mạch thay thế không?', 'oat milk = sữa yến mạch; popular substitution', 116, true),
('daily-cafe-003', 'daily-life', 'Make it decaf, please.', 'Không cà phê nhé (decaf).', 'decaf = không caffeine', 117, true),
('daily-cafe-004', 'daily-life', 'Can I have an extra shot of espresso?', 'Cho thêm một shot espresso được không?', 'extra shot = thêm một phần espresso', 118, true),
('daily-cafe-005', 'daily-life', 'Is this seat taken?', 'Ghế này có ai ngồi chưa?', 'Câu hỏi khi muốn ngồi cạnh người lạ', 119, true),
('daily-cafe-006', 'daily-life', 'Do you have free Wi-Fi here? What''s the password?', 'Ở đây có Wi-Fi miễn phí không? Mật khẩu là gì?', '', 120, true),
('daily-cafe-007', 'daily-life', 'Could I get this to go?', 'Tôi có thể lấy mang về không?', 'to go = mang về; dine in = ăn tại chỗ', 121, true),
('daily-cafe-008', 'daily-life', 'I''ll have the same as her.', 'Cho tôi giống như của cô ấy.', 'Câu nhanh gọn khi muốn gọi giống người khác', 122, true),
('daily-cafe-009', 'daily-life', 'Can I get a refill?', 'Tôi có thể xin thêm không?', 'refill = rót thêm (thường miễn phí ở Mỹ)', 123, true),
('daily-cafe-010', 'daily-life', 'Do you have any dairy-free options?', 'Bạn có lựa chọn không có sữa không?', 'dairy-free = không chứa sản phẩm từ sữa', 124, true),
('daily-cafe-011', 'daily-life', 'I''d like to order a slice of cheesecake too.', 'Cho tôi thêm một miếng cheesecake nữa.', '', 125, true),
('daily-cafe-012', 'daily-life', 'Could I get a receipt?', 'Cho tôi hóa đơn được không?', '', 126, true),
('daily-restaurant-001', 'daily-life', 'Do you have a table for two available?', 'Bạn có bàn trống cho 2 người không?', '', 127, true),
('daily-restaurant-002', 'daily-life', 'I have a reservation under Dr. [Name] at 7 pm.', 'Tôi có đặt bàn với tên bác sĩ [Tên] lúc 7 giờ tối.', '', 128, true),
('daily-restaurant-003', 'daily-life', 'Could we see the menu, please?', 'Cho chúng tôi xem thực đơn được không?', '', 129, true),
('daily-restaurant-004', 'daily-life', 'What do you recommend? What''s the specialty here?', 'Bạn gợi ý món gì? Đặc sản ở đây là gì?', '', 130, true),
('daily-restaurant-005', 'daily-life', 'I''m allergic to shellfish — no shrimp, crab, or oyster.', 'Tôi dị ứng hải sản có vỏ — không tôm, cua, hay hàu.', 'shellfish = hải sản có vỏ', 131, true),
('daily-restaurant-006', 'daily-life', 'I''d like my steak medium-rare, please.', 'Cho tôi bít tết chín tái vừa nhé.', 'rare/medium-rare/medium/well-done', 132, true),
('daily-restaurant-007', 'daily-life', 'Could I substitute the fries for a salad?', 'Tôi có thể đổi khoai chiên lấy salad không?', 'substitute = đổi, thay thế', 133, true),
('daily-restaurant-008', 'daily-life', 'Excuse me, we''ve been waiting for 20 minutes.', 'Xin lỗi, chúng tôi đã đợi 20 phút rồi.', 'Lịch sự nhưng rõ ràng', 134, true),
('daily-restaurant-009', 'daily-life', 'This isn''t what I ordered. I asked for the salmon.', 'Đây không phải món tôi gọi. Tôi đã gọi cá hồi.', '', 135, true),
('daily-restaurant-010', 'daily-life', 'Could we get some more water, please?', 'Cho chúng tôi thêm nước được không?', '', 136, true),
('daily-restaurant-011', 'daily-life', 'Everything was delicious. Compliments to the chef.', 'Mọi thứ đều ngon. Khen đầu bếp giúp tôi nhé.', '', 137, true),
('daily-restaurant-012', 'daily-life', 'Could we get the bill please? We''ll split it.', 'Cho chúng tôi tính tiền nhé? Chúng tôi chia đôi.', 'split the bill = chia tiền', 138, true),
('daily-restaurant-013', 'daily-life', 'Is service charge included in the bill?', 'Phí phục vụ có bao gồm trong hóa đơn không?', '', 139, true),
('daily-transport-001', 'daily-life', 'Could you take me to the Marriott Hotel on Nguyen Hue Street?', 'Bạn có thể đưa tôi đến khách sạn Marriott trên đường Nguyễn Huệ không?', '', 140, true),
('daily-transport-002', 'daily-life', 'How long will it take to get there?', 'Mất bao lâu để đến đó?', '', 141, true),
('daily-transport-003', 'daily-life', 'Could you please turn on the air conditioning?', 'Bạn có thể bật điều hòa được không?', '', 142, true),
('daily-transport-004', 'daily-life', 'Please drop me off at the corner.', 'Vui lòng để tôi xuống ở góc đường.', 'drop off = để xuống (xe)', 143, true),
('daily-transport-005', 'daily-life', 'Keep the change.', 'Bạn giữ tiền lẻ đi.', 'Câu boa cho tài xế', 144, true),
('daily-transport-006', 'daily-life', 'Excuse me, how do I get to the nearest subway station?', 'Xin lỗi, tôi đi đến trạm tàu điện ngầm gần nhất như thế nào?', '', 145, true),
('daily-transport-007', 'daily-life', 'Is this the right bus for the city centre?', 'Đây có phải xe buýt đi trung tâm thành phố không?', '', 146, true),
('daily-transport-008', 'daily-life', 'Where should I get off for the museum?', 'Tôi nên xuống trạm nào để đến bảo tàng?', 'get off = xuống (xe buýt/tàu)', 147, true),
