('daily-social-002', 'daily-life', 'That''s a good point, but I see it slightly differently.', 'Đó là điểm hay, nhưng tôi thấy hơi khác một chút.', 'Cách phản bác lịch sự', 201, true),
('daily-social-003', 'daily-life', 'I completely agree with you on that.', 'Tôi hoàn toàn đồng ý với bạn về điều đó.', '', 202, true),
('daily-social-004', 'daily-life', 'I''m not sure I agree — could you explain more?', 'Tôi không chắc đồng ý — bạn có thể giải thích thêm không?', '', 203, true),
('daily-social-005', 'daily-life', 'To be honest, I''m not really a fan of that idea.', 'Thật ra, tôi không mấy hứng thú với ý tưởng đó.', 'to be honest = thật ra, nói thật', 204, true),
('daily-social-006', 'daily-life', 'That''s fascinating! I hadn''t thought of it that way.', 'Thú vị thật! Tôi chưa nghĩ theo hướng đó.', '', 205, true),
('daily-social-007', 'daily-life', 'I''m really impressed by how they managed that.', 'Tôi thực sự ấn tượng với cách họ xử lý điều đó.', '', 206, true),
('daily-social-008', 'daily-life', 'Honestly, I''m a bit overwhelmed at the moment.', 'Thật ra, tôi đang hơi bị quá tải lúc này.', 'overwhelmed = quá tải, ngập đầu', 207, true),
('daily-social-009', 'daily-life', 'I couldn''t agree more — that''s exactly how I feel.', 'Tôi đồng ý hoàn toàn — đó chính xác là cảm giác của tôi.', '', 208, true),
('daily-social-010', 'daily-life', 'Let me think about that for a moment.', 'Để tôi suy nghĩ một chút.', 'Câu hay để câu giờ khi cần nghĩ', 209, true),
