('daily-plans-003', 'daily-life', 'I was wondering if you''d like to join us for drinks?', 'Tôi tự hỏi liệu bạn có muốn cùng chúng tôi đi uống không?', 'Cách mời lịch sự, ít áp lực hơn', 214, true),
('daily-plans-004', 'daily-life', 'That sounds great! What time were you thinking?', 'Nghe hay đó! Bạn nghĩ khoảng mấy giờ?', '', 215, true),
('daily-plans-005', 'daily-life', 'I''d love to, but I have a prior commitment.', 'Tôi rất muốn, nhưng tôi có việc đã hẹn trước.', 'prior commitment = việc đã có trước', 216, true),
('daily-plans-006', 'daily-life', 'Could we do it another time? I''m swamped this week.', 'Chúng ta có thể làm lần khác không? Tuần này tôi kẹt lắm.', 'swamped = ngập đầu công việc', 217, true),
