('daily-plans-008', 'daily-life', 'Count me in!', 'Tính tôi vào!', 'count me in = tôi tham gia', 219, true),
('daily-plans-009', 'daily-life', 'I''ll have to take a rain check on that.', 'Tôi phải hoãn lại lần này.', 'rain check = hẹn lại lần khác (thành ngữ Mỹ)', 220, true),
('daily-plans-010', 'daily-life', 'Do you want to split a cab to the restaurant?', 'Bạn có muốn đi chung taxi đến nhà hàng không?', 'split a cab = đi chung taxi chia tiền', 221, true),
