('daily-plans-012', 'daily-life', 'Dutch? We''ll split the bill.', 'Chia đôi nhé? Chúng ta chia tiền.', 'go Dutch = chia tiền', 223, true),
('daily-problems-001', 'daily-life', 'Excuse me, I think there''s been a mistake with my order.', 'Xin lỗi, tôi nghĩ có sự nhầm lẫn với đơn của tôi.', '', 224, true),
('daily-problems-002', 'daily-life', 'I''m not happy with the service I received today.', 'Tôi không hài lòng với dịch vụ hôm nay.', 'Câu phàn nàn nhẹ nhàng', 225, true),
