('daily-problems-006', 'daily-life', 'I was overcharged. The menu says $15 but I was charged $20.', 'Tôi bị tính tiền sai. Menu ghi 15$ nhưng tôi bị tính 20$.', '', 229, true),
('daily-problems-007', 'daily-life', 'I''d like a refund, please.', 'Tôi muốn được hoàn tiền.', 'refund = hoàn tiền', 230, true),
('daily-problems-008', 'daily-life', 'There''s been a mix-up with my booking.', 'Có sự nhầm lẫn với đặt chỗ của tôi.', 'mix-up = nhầm lẫn', 231, true),
('daily-problems-009', 'daily-life', 'I understand you''re busy, but this has been going on for a while.', 'Tôi hiểu bạn đang bận, nhưng vấn đề này đã kéo dài một lúc rồi.', '', 232, true),
('daily-problems-010', 'daily-life', 'I appreciate your help in sorting this out.', 'Tôi đánh giá cao sự giúp đỡ của bạn trong việc giải quyết điều này.', 'sorting out = giải quyết, sắp xếp', 233, true),
('daily-problems-011', 'daily-life', 'Could I have that in writing?', 'Tôi có thể có điều đó bằng văn bản không?', '', 234, true),
('daily-problems-012', 'daily-life', 'I''ll follow up with an email.', 'Tôi sẽ theo dõi bằng email.', '', 235, true),
('daily-clarification-001', 'daily-life', 'Sorry, I didn''t quite catch that. Could you repeat?', 'Xin lỗi, tôi không bắt kịp. Bạn có thể nói lại không?', 'CÂU QUAN TRỌNG NHẤT — dùng tự tin!', 236, true),
('daily-clarification-002', 'daily-life', 'Could you slow down a little? My English is still improving.', 'Bạn có thể nói chậm hơn không? Tiếng Anh của tôi vẫn đang cải thiện.', '', 237, true),
('daily-clarification-003', 'daily-life', 'I''m sorry, could you say that in a different way?', 'Xin lỗi, bạn có thể diễn đạt theo cách khác không?', '', 238, true),
('daily-clarification-004', 'daily-life', 'Could you spell that out for me?', 'Bạn có thể đánh vần cho tôi không?', 'Khi không nghe rõ tên/từ lạ', 239, true),
('daily-clarification-005', 'daily-life', 'What does [word] mean exactly?', '[từ] có nghĩa chính xác là gì?', '', 240, true),
('daily-clarification-006', 'daily-life', 'So if I understand correctly, you''re saying that...', 'Vậy nếu tôi hiểu đúng, bạn đang nói rằng...', 'Xác nhận lại ý hiểu — rất chuyên nghiệp', 241, true),
('daily-clarification-007', 'daily-life', 'Let me make sure I understand — you mean...?', 'Để tôi chắc chắn tôi hiểu — ý bạn là...?', '', 242, true),
('daily-clarification-008', 'daily-life', 'Could you write that down? I want to make sure I get it right.', 'Bạn có thể viết ra không? Tôi muốn đảm bảo hiểu đúng.', '', 243, true),
('daily-clarification-009', 'daily-life', 'Sorry — the line is a bit unclear. Could you repeat that?', 'Xin lỗi — đường dây hơi không rõ. Bạn có thể nói lại không?', 'Dùng qua điện thoại', 244, true),
('daily-clarification-010', 'daily-life', 'I think I understand, but let me confirm — you said [X], right?', 'Tôi nghĩ tôi hiểu, nhưng để tôi xác nhận — bạn nói [X], đúng không?', '', 245, true),
('daily-clarification-011', 'daily-life', 'Bear with me — I''m still thinking of the right word.', 'Chịu khó đợi tôi một chút — tôi vẫn đang nghĩ từ phù hợp.', 'bear with me = kiên nhẫn với tôi', 246, true),
('daily-clarification-012', 'daily-life', 'Excuse my English — I''m still learning.', 'Xin lỗi vì tiếng Anh của tôi — tôi vẫn đang học.', 'Câu tự tin và chân thành', 247, true),
('med-conf-presentation-001', 'conference', 'Good morning everyone. I''d like to present an interesting case.', 'Chào buổi sáng mọi người. Tôi muốn trình bày một ca thú vị.', '', 248, true),
('med-conf-presentation-002', 'conference', 'The patient is a 45-year-old male presenting with a 3-week history of hearing loss.', 'Bệnh nhân nam 45 tuổi, bệnh sử 3 tuần giảm thính lực.', '', 249, true),
('med-conf-presentation-003', 'conference', 'On examination, we found significant cerumen impaction bilaterally.', 'Khi khám, chúng tôi thấy ráy tai tắc nghẽn 2 bên.', 'cerumen impaction = ráy tai tắc; bilateral = 2 bên', 250, true),
('med-conf-presentation-004', 'conference', 'The CT scan revealed opacification of the right maxillary sinus.', 'CT scan cho thấy mờ đục xoang hàm phải.', 'maxillary sinus = xoang hàm', 251, true),
('med-conf-presentation-005', 'conference', 'After treatment, the patient showed significant improvement.', 'Sau điều trị, bệnh nhân cải thiện đáng kể.', '', 252, true),
('med-conf-presentation-006', 'conference', 'In conclusion, this case highlights the importance of early diagnosis.', 'Kết luận, ca này nhấn mạnh tầm quan trọng của chẩn đoán sớm.', '', 253, true),
('med-conf-presentation-007', 'conference', 'I''d be happy to take any questions.', 'Tôi sẵn sàng nhận câu hỏi.', '', 254, true),
('med-conf-networking-001', 'conference', 'Your presentation was very insightful. I have a similar experience in my practice.', 'Bài trình bày của bạn rất sâu sắc. Tôi có kinh nghiệm tương tự trong thực hành.', '', 255, true),
('med-conf-networking-002', 'conference', 'Could we exchange contact details? I''d love to collaborate.', 'Chúng ta có thể trao đổi thông tin liên hệ không? Tôi muốn hợp tác.', '', 256, true),
('med-conf-networking-003', 'conference', 'Which hospital do you work at?', 'Bạn làm ở bệnh viện nào?', '', 257, true),
('med-conf-networking-004', 'conference', 'Have you published any papers on this topic?', 'Bạn có đăng bài về chủ đề này chưa?', 'paper = bài báo khoa học', 258, true),
('med-conf-networking-005', 'conference', 'What''s your approach to difficult cases like this?', 'Cách tiếp cận của bạn với các ca khó như thế này là gì?', '', 259, true),
('med-conf-networking-006', 'conference', 'We use a slightly different protocol in Vietnam. Let me tell you about it.', 'Ở Việt Nam chúng tôi dùng phác đồ hơi khác. Để tôi kể cho bạn nghe.', '', 260, true),
('med-conf-discussion-001', 'conference', 'I agree with your point, however I''d like to add...', 'Tôi đồng ý với quan điểm của bạn, nhưng tôi muốn bổ sung...', '', 261, true),
('med-conf-discussion-002', 'conference', 'Based on the evidence, I think the first-line treatment should be...', 'Dựa trên bằng chứng, tôi nghĩ điều trị hàng đầu nên là...', '', 262, true),
('med-conf-discussion-003', 'conference', 'What does the current literature say about this?', 'Tài liệu hiện tại nói gì về vấn đề này?', 'literature = tài liệu y văn', 263, true),
('med-conf-discussion-004', 'conference', 'That''s a valid point. We''ve seen similar results.', 'Đó là điểm hợp lệ. Chúng tôi cũng thấy kết quả tương tự.', '', 264, true),
('med-conf-discussion-005', 'conference', 'Could you clarify what you mean by that?', 'Bạn có thể làm rõ ý bạn không?', 'Câu lịch sự để hỏi lại khi chưa hiểu.', 265, true);
insert into scenarios (slug, title, icon, level, description, hint, system_prompt, opening_line, sort_order, published) values
('new-patient', 'New Patient — Ear Pain', '🧑‍🦱', 'beginner', 'AI: Patient with ear pain for 3 days. You: take history, examine, diagnose.', 'Ask: How long? Which ear? Pain level? Fever? Any discharge? Recent swimming?', 'You are playing the role of a patient visiting an ENT doctor.
insert into listening_lessons (slug, title, source, level, duration, transcript, connected_speech, vocab, quiz, sort_order, published) values
('lesson-001', 'At the Doctor''s Office', 'VOA Learning English', 'beginner', '2 min', '[{"text":"Good morning. How can I help you today?","vn":"Chao buoi sang. Toi co the giup gi cho ban?"},{"text":"I''ve been having headaches for the past week.","vn":"Toi bi dau dau ca tuan qua."},{"text":"Can you describe the pain? Is it sharp or dull?","vn":"Ban mo ta con dau duoc khong? Dau nhoi hay dau am?"},{"text":"It''s a dull pain, mostly in the front of my head.","vn":"Dau am am, chu yeu o phia truoc dau."},{"text":"How often do you get these headaches?","vn":"Ban bi dau dau thuong xuyen khong?"},{"text":"Almost every day, usually in the afternoon.","vn":"Gan nhu moi ngay, thuong vao buoi chieu."},{"text":"Are you drinking enough water? Dehydration can cause headaches.","vn":"Ban co uong du nuoc khong? Mat nuoc co the gay dau dau."},{"text":"I probably don''t drink enough. I''ll try to drink more.","vn":"Co le toi khong uong du. Toi se co uong nhieu hon."}]', '[{"phrase":"How can I help you","phenomenon":"Linking: can_I → /kænaɪ/"},{"phrase":"for the past week","phenomenon":"Weak form: ''for'' → /fər/"},{"phrase":"Is it sharp or dull","phenomenon":"Linking: sharp_or → /ʃɑːrpɔːr/"}]', '[{"word":"headache","phonetic":"/ˈhedeɪk/","meaning":"dau dau"},{"word":"sharp pain","phonetic":"/ʃɑːrp peɪn/","meaning":"dau nhoi"},{"word":"dull pain","phonetic":"/dʌl peɪn/","meaning":"dau am"},{"word":"dehydration","phonetic":"/ˌdiːhaɪˈdreɪʃn/","meaning":"mat nuoc"}]', '[{"question":"What is the patient''s main complaint?","options":["Stomach pain","Headaches","Coughing","Fever"],"answer":1},{"question":"How often does the patient get headaches?","options":["Once a week","Almost every day","Only at night","Once a month"],"answer":1},{"question":"What might be causing the headaches?","options":["Too much exercise","Dehydration","Bad food","Cold weather"],"answer":1}]', 0, true),
('lesson-002', 'Ordering Food at a Restaurant', 'BBC Learning English', 'beginner', '2 min', '[{"text":"Good evening. Welcome to The Garden. Do you have a reservation?","vn":"Chao buoi toi. Chao mung den The Garden. Ban co dat ban truoc khong?"},{"text":"Yes, under the name Wilson. A table for two, please.","vn":"Co, ten Wilson. Ban cho hai nguoi."},{"text":"Right this way. Here are your menus.","vn":"Moi di theo toi. Day la thuc don."},{"text":"Thank you. Could we have a few minutes to decide?","vn":"Cam on. Cho chung toi vai phut de chon nhe?"},{"text":"Of course. Would you like something to drink while you wait?","vn":"Duoc a. Ban muon uong gi trong luc cho?"},{"text":"I''ll have a glass of water, please. And she''ll have an orange juice.","vn":"Cho toi mot ly nuoc. Va co ay uong nuoc cam."},{"text":"Are you ready to order? What would you like?","vn":"Ban san sang goi mon chua? Ban muon gi?"},{"text":"I''d like the grilled salmon with vegetables, please.","vn":"Cho toi ca hoi nuong voi rau."},{"text":"Excellent choice. And for dessert?","vn":"Lua chon tuyet voi. Con trang mieng?"},{"text":"We''ll decide later, thank you.","vn":"Chung toi se chon sau, cam on."}]', '[{"phrase":"Do you have a reservation","phenomenon":"Linking: have_a → /hævə/"},{"phrase":"Would you like","phenomenon":"Weak form: ''would you'' → /wʊdʒə/"},{"phrase":"I''ll have a glass of","phenomenon":"Contraction + linking: I''ll_have_a → /aɪlhævə/"}]', '[{"word":"reservation","phonetic":"/ˌrezərˈveɪʃn/","meaning":"dat ban/phong truoc"},{"word":"menu","phonetic":"/ˈmenjuː/","meaning":"thuc don"},{"word":"grilled","phonetic":"/ɡrɪld/","meaning":"nuong"},{"word":"dessert","phonetic":"/dɪˈzɜːrt/","meaning":"trang mieng"}]', '[{"question":"How many people are dining?","options":["One","Two","Three","Four"],"answer":1},{"question":"What does the man order?","options":["Steak","Grilled salmon","Pasta","Chicken"],"answer":1},{"question":"''I''d like'' is a polite way to say:","options":["I need","I want","I demand","I must have"],"answer":1}]', 1, true),
('lesson-003', 'Describing Symptoms to a Doctor', 'VOA Learning English', 'intermediate', '3 min', '[{"text":"Doctor, I''ve been feeling unwell for about a week now.","vn":"Bac si, toi thay khong khoe khoang mot tuan nay."},{"text":"I''m sorry to hear that. Can you tell me more about your symptoms?","vn":"Toi rat tiec. Ban co the noi them ve cac trieu chung khong?"},{"text":"Well, it started with a sore throat, and then I developed a cough.","vn":"Bat dau bang dau hong, roi toi bi ho."},{"text":"Is the cough productive? I mean, are you coughing up any mucus?","vn":"Ho co dom khong? Toi muon noi, ban ho co ra chat nhay khong?"},{"text":"Yes, it''s thick and yellowish. And I''ve had a fever on and off.","vn":"Co, dom dac va mau vang. Va toi bi sot luc co luc khong."},{"text":"Have you taken any medication so far?","vn":"Ban da uong thuoc gi chua?"},{"text":"Just some over-the-counter pain relievers for the fever.","vn":"Chi uong thuoc giam dau khong ke don de ha sot thoi."},{"text":"I''d like to do a quick examination. Please open your mouth and say ''aah''.","vn":"Toi muon kham nhanh. Vui long ha mieng va noi ''aah''."},{"text":"Your throat is quite inflamed. I''m going to prescribe antibiotics.","vn":"Hong ban bi viem kha nang. Toi se ke khang sinh."},{"text":"How long should I take the antibiotics?","vn":"Toi nen uong khang sinh bao lau?"},{"text":"For seven days. Make sure you complete the full course, even if you feel better.","vn":"Bay ngay. Nho uong het lieu, ngay ca khi ban thay tot hon."}]', '[{"phrase":"I''ve been feeling","phenomenon":"Contraction: I''ve → /aɪv/"},{"phrase":"coughing up any","phenomenon":"Linking: up_any → /ʌpeni/"},{"phrase":"on and off","phenomenon":"Phrasal: luc co luc khong"}]', '[{"word":"sore throat","phonetic":"/sɔːr θroʊt/","meaning":"dau hong"},{"word":"productive cough","phonetic":"/prəˈdʌktɪv kɒf/","meaning":"ho co dom"},{"word":"mucus","phonetic":"/ˈmjuːkəs/","meaning":"chat nhay, dom"},{"word":"inflamed","phonetic":"/ɪnˈfleɪmd/","meaning":"bi viem"},{"word":"antibiotics","phonetic":"/ˌæntɪbaɪˈɒtɪks/","meaning":"khang sinh"},{"word":"over-the-counter","phonetic":"/ˌoʊvər ðə ˈkaʊntər/","meaning":"khong ke don"}]', '[{"question":"What was the first symptom?","options":["Cough","Fever","Sore throat","Headache"],"answer":2},{"question":"What color is the mucus?","options":["Clear","Green","Yellowish","Red"],"answer":2},{"question":"How long should the patient take antibiotics?","options":["3 days","5 days","7 days","10 days"],"answer":2},{"question":"''Over-the-counter'' means:","options":["Very expensive","Available without prescription","Only in hospitals","Imported"],"answer":1}]', 2, true),
('lesson-004', 'Making a Phone Appointment', 'BBC Learning English', 'beginner', '2 min', '[{"text":"Good morning, City Medical Center. How may I help you?","vn":"Chao buoi sang, Trung tam Y te Thanh pho. Toi giup gi duoc?"},{"text":"Hello, I''d like to make an appointment with Dr. Smith, please.","vn":"Xin chao, toi muon dat lich hen voi bac si Smith."},{"text":"Is this for a routine check-up or is it urgent?","vn":"Day la kham dinh ky hay khan cap?"},{"text":"It''s not urgent, but I''d like to be seen this week if possible.","vn":"Khong khan cap, nhung toi muon duoc kham tuan nay neu duoc."},{"text":"Let me check the schedule. Dr. Smith has an opening on Thursday at 2 PM.","vn":"De toi xem lich. Bac si Smith con lich trong vao thu Nam luc 2 gio chieu."},{"text":"Thursday at 2 PM works for me. Could I get a morning slot instead?","vn":"Thu Nam 2 gio duoc. Co lich buoi sang khong?"},{"text":"We have 10 AM available on Friday. Would that work?","vn":"Chung toi co lich 10 gio sang thu Sau. Duoc khong?"},{"text":"Friday at 10 AM is perfect. Thank you!","vn":"Thu Sau 10 gio sang hoan hao. Cam on!"},{"text":"May I have your name and date of birth, please?","vn":"Cho toi xin ten va ngay sinh cua ban?"},{"text":"It''s Tran, T-R-A-N. Date of birth: March 15th, 1985.","vn":"Tran, T-R-A-N. Ngay sinh: 15 thang 3 nam 1985."}]', '[{"phrase":"How may I help you","phenomenon":"Weak form: may_I → /meɪaɪ/"},{"phrase":"I''d like to","phenomenon":"Contraction: I''d → /aɪd/"},{"phrase":"works for me","phenomenon":"Common expression: phu hop voi toi"}]', '[{"word":"appointment","phonetic":"/əˈpɔɪntmənt/","meaning":"lich hen"},{"word":"routine check-up","phonetic":"/ruːˈtiːn ˈtʃekʌp/","meaning":"kham dinh ky"},{"word":"urgent","phonetic":"/ˈɜːrdʒənt/","meaning":"khan cap"},{"word":"opening/slot","phonetic":"/ˈoʊpənɪŋ/","meaning":"lich trong"}]', '[{"question":"Why is the caller making an appointment?","options":["Emergency","Routine check-up","Surgery","Getting test results"],"answer":1},{"question":"When is the final appointment?","options":["Thursday 2 PM","Friday 10 AM","Wednesday 9 AM","Monday 3 PM"],"answer":1},{"question":"''May I have your name?'' is asking for...","options":["Permission","Information","An opinion","A favor"],"answer":1}]', 3, true),
('lesson-005', 'Explaining a Medical Procedure', 'VOA Health', 'intermediate', '3 min', '[{"text":"Before we begin, I''d like to explain what we''re going to do today.","vn":"Truoc khi bat dau, toi muon giai thich hom nay chung ta se lam gi."},{"text":"We''re going to perform a minor procedure to examine your ear more closely.","vn":"Chung toi se thuc hien mot thu thuat nho de kham tai ban ky hon."},{"text":"First, I''ll apply a local anesthetic so you won''t feel any pain.","vn":"Dau tien, toi se boi thuoc te tai cho de ban khong thay dau."},{"text":"Then, I''ll use a small instrument called an otoscope to look inside.","vn":"Sau do, toi se dung dung cu nho goi la den soi tai de nhin ben trong."},{"text":"You might feel some pressure, but it shouldn''t be painful.","vn":"Ban co the thay hoi ap luc, nhung se khong dau."},{"text":"The whole thing should take about 10 to 15 minutes.","vn":"Toan bo qua trinh khoang 10 den 15 phut."},{"text":"Do you have any questions before we start?","vn":"Ban co cau hoi gi truoc khi chung ta bat dau khong?"},{"text":"Will I be able to hear normally after the procedure?","vn":"Sau thu thuat toi nghe binh thuong duoc khong?"},{"text":"Yes, your hearing should return to normal within a day or two.","vn":"Co, thinh luc cua ban se tro lai binh thuong trong mot hai ngay."},{"text":"If you experience any discomfort afterward, please don''t hesitate to call us.","vn":"Neu ban thay kho chiu sau do, dung ngai goi cho chung toi."}]', '[{"phrase":"what we''re going to do","phenomenon":"Weak form: ''to'' → /tə/; contraction: we''re → /wɪər/"},{"phrase":"won''t feel any pain","phenomenon":"Contraction: won''t → /woʊnt/"},{"phrase":"don''t hesitate to","phenomenon":"Common phrase: dung ngai"}]', '[{"word":"procedure","phonetic":"/prəˈsiːdʒər/","meaning":"thu thuat"},{"word":"local anesthetic","phonetic":"/ˌloʊkl ænəsˈθetɪk/","meaning":"thuoc te tai cho"},{"word":"otoscope","phonetic":"/ˈoʊtəskoʊp/","meaning":"den soi tai"},{"word":"discomfort","phonetic":"/dɪsˈkʌmfərt/","meaning":"kho chiu"}]', '[{"question":"What instrument will the doctor use?","options":["Stethoscope","Otoscope","Thermometer","X-ray"],"answer":1},{"question":"How long will the procedure take?","options":["5 minutes","10-15 minutes","30 minutes","1 hour"],"answer":1},{"question":"''Don''t hesitate to call us'' means:","options":["Don''t call us","Call us anytime","Wait before calling","Call emergency only"],"answer":1}]', 4, true);
